00376 ImDrawListSharedData::ImDrawListSharedData()
00377 {
00378     memset(this, 0, sizeof(*this));
00379     for (int i = 0; i < IM_ARRAYSIZE(ArcFastVtx); i++)
00380     {
00381         const float a = ((float)i * 2 * IM_PI) / (float)IM_ARRAYSIZE(ArcFastVtx);
00382         ArcFastVtx[i] = ImVec2(ImCos(a), ImSin(a));
00383     }
00384     ArcFastRadiusCutoff = IM_DRAWLIST_CIRCLE_AUTO_SEGMENT_CALC_R(IM_DRAWLIST_ARCFAST_SAMPLE_MAX, CircleSegmentMaxError);
00385 }
00386 
00387 void ImDrawListSharedData::SetCircleTessellationMaxError(float max_error)
00388 {
00389     if (CircleSegmentMaxError == max_error)
00390         return;
00391 
00392     IM_ASSERT(max_error > 0.0f);
00393     CircleSegmentMaxError = max_error;
00394     for (int i = 0; i < IM_ARRAYSIZE(CircleSegmentCounts); i++)
00395     {
00396         const float radius = (float)i;
00397         CircleSegmentCounts[i] = (ImU8)((i > 0) ? IM_DRAWLIST_CIRCLE_AUTO_SEGMENT_CALC(radius, CircleSegmentMaxError) : IM_DRAWLIST_ARCFAST_SAMPLE_MAX);
00398     }
00399     ArcFastRadiusCutoff = IM_DRAWLIST_CIRCLE_AUTO_SEGMENT_CALC_R(IM_DRAWLIST_ARCFAST_SAMPLE_MAX, CircleSegmentMaxError);
00400 }
