00402 // Initialize before use in a new frame. We always have a command ready in the buffer.
00403 // In the majority of cases, you would want to call PushClipRect() and PushTextureID() after this.
00404 void ImDrawList::_ResetForNewFrame()
00405 {
00406     // Verify that the ImDrawCmd fields we want to memcmp() are contiguous in memory.
00407     IM_STATIC_ASSERT(offsetof(ImDrawCmd, ClipRect) == 0);
00408     IM_STATIC_ASSERT(offsetof(ImDrawCmd, TextureId) == sizeof(ImVec4));
00409     IM_STATIC_ASSERT(offsetof(ImDrawCmd, VtxOffset) == sizeof(ImVec4) + sizeof(ImTextureID));
00410     if (_Splitter._Count > 1)
00411         _Splitter.Merge(this);
00412 
00413     CmdBuffer.resize(0);
00414     IdxBuffer.resize(0);
00415     VtxBuffer.resize(0);
00416     Flags = _Data->InitialFlags;
00417     memset(&_CmdHeader, 0, sizeof(_CmdHeader));
00418     _VtxCurrentIdx = 0;
00419     _VtxWritePtr = NULL;
00420     _IdxWritePtr = NULL;
00421     _ClipRectStack.resize(0);
00422     _TextureIdStack.resize(0);
00423     _Path.resize(0);
00424     _Splitter.Clear();
00425     CmdBuffer.push_back(ImDrawCmd());
00426     _FringeScale = 1.0f;
00427 }
