00454 void ImDrawList::AddDrawCmd()
00455 {
00456     ImDrawCmd draw_cmd;
00457     draw_cmd.ClipRect = _CmdHeader.ClipRect;    // Same as calling ImDrawCmd_HeaderCopy()
00458     draw_cmd.TextureId = _CmdHeader.TextureId;
00459     draw_cmd.VtxOffset = _CmdHeader.VtxOffset;
00460     draw_cmd.IdxOffset = IdxBuffer.Size;
00461 
00462     IM_ASSERT(draw_cmd.ClipRect.x <= draw_cmd.ClipRect.z && draw_cmd.ClipRect.y <= draw_cmd.ClipRect.w);
00463     CmdBuffer.push_back(draw_cmd);
00464 }
00465 
00466 // Pop trailing draw command (used before merging or presenting to user)
00467 // Note that this leaves the ImDrawList in a state unfit for further commands, as most code assume that CmdBuffer.Size > 0 && CmdBuffer.back().UserCallback == NULL
00468 void ImDrawList::_PopUnusedDrawCmd()
00469 {
00470     while (CmdBuffer.Size > 0)
00471     {
00472         ImDrawCmd* curr_cmd = &CmdBuffer.Data[CmdBuffer.Size - 1];
00473         if (curr_cmd->ElemCount != 0 || curr_cmd->UserCallback != NULL)
00474             return;// break;
00475         CmdBuffer.pop_back();
00476     }
00477 }
00478 
00479 void ImDrawList::AddCallback(ImDrawCallback callback, void* callback_data)
00480 {
00481     IM_ASSERT_PARANOID(CmdBuffer.Size > 0);
00482     ImDrawCmd* curr_cmd = &CmdBuffer.Data[CmdBuffer.Size - 1];
00483     IM_ASSERT(curr_cmd->UserCallback == NULL);
00484     if (curr_cmd->ElemCount != 0)
00485     {
00486         AddDrawCmd();
00487         curr_cmd = &CmdBuffer.Data[CmdBuffer.Size - 1];
00488     }
00489     curr_cmd->UserCallback = callback;
00490     curr_cmd->UserCallbackData = callback_data;
00491 
00492     AddDrawCmd(); // Force a new command after us (see comment below)
00493 }
00494 
00495 // Compare ClipRect, TextureId and VtxOffset with a single memcmp()
00496 #define ImDrawCmd_HeaderSize                            (offsetof(ImDrawCmd, VtxOffset) + sizeof(unsigned int))
00497 #define ImDrawCmd_HeaderCompare(CMD_LHS, CMD_RHS)       (memcmp(CMD_LHS, CMD_RHS, ImDrawCmd_HeaderSize))    // Compare ClipRect, TextureId, VtxOffset
00498 #define ImDrawCmd_HeaderCopy(CMD_DST, CMD_SRC)          (memcpy(CMD_DST, CMD_SRC, ImDrawCmd_HeaderSize))    // Copy ClipRect, TextureId, VtxOffset
00499 #define ImDrawCmd_AreSequentialIdxOffset(CMD_0, CMD_1)  (CMD_0->IdxOffset + CMD_0->ElemCount == CMD_1->IdxOffset)
00500 
00501 // Try to merge two last draw commands
00502 void ImDrawList::_TryMergeDrawCmds()
00503 {
00504     IM_ASSERT_PARANOID(CmdBuffer.Size > 0);
00505     ImDrawCmd* curr_cmd = &CmdBuffer.Data[CmdBuffer.Size - 1];
00506     ImDrawCmd* prev_cmd = curr_cmd - 1;
00507     if (ImDrawCmd_HeaderCompare(curr_cmd, prev_cmd) == 0 && ImDrawCmd_AreSequentialIdxOffset(prev_cmd, curr_cmd) && curr_cmd->UserCallback == NULL && prev_cmd->UserCallback == NULL)
00508     {
00509         prev_cmd->ElemCount += curr_cmd->ElemCount;
00510         CmdBuffer.pop_back();
00511     }
00512 }
00513 
00514 // Our scheme may appears a bit unusual, basically we want the most-common calls AddLine AddRect etc. to not have to perform any check so we always have a command ready in the stack.
00515 // The cost of figuring out if a new command has to be added or if we can merge is paid in those Update** functions only.
00516 void ImDrawList::_OnChangedClipRect()
00517 {
00518     // If current command is used with different settings we need to add a new command
00519     IM_ASSERT_PARANOID(CmdBuffer.Size > 0);
00520     ImDrawCmd* curr_cmd = &CmdBuffer.Data[CmdBuffer.Size - 1];
00521     if (curr_cmd->ElemCount != 0 && memcmp(&curr_cmd->ClipRect, &_CmdHeader.ClipRect, sizeof(ImVec4)) != 0)
00522     {
00523         AddDrawCmd();
00524         return;
00525     }
00526     IM_ASSERT(curr_cmd->UserCallback == NULL);
00527 
00528     // Try to merge with previous command if it matches, else use current command
00529     ImDrawCmd* prev_cmd = curr_cmd - 1;
00530     if (curr_cmd->ElemCount == 0 && CmdBuffer.Size > 1 && ImDrawCmd_HeaderCompare(&_CmdHeader, prev_cmd) == 0 && ImDrawCmd_AreSequentialIdxOffset(prev_cmd, curr_cmd) && prev_cmd->UserCallback == NULL)
00531     {
00532         CmdBuffer.pop_back();
00533         return;
00534     }
00535 
00536     curr_cmd->ClipRect = _CmdHeader.ClipRect;
00537 }
00538 
00539 void ImDrawList::_OnChangedTextureID()
00540 {
00541     // If current command is used with different settings we need to add a new command
00542     IM_ASSERT_PARANOID(CmdBuffer.Size > 0);
00543     ImDrawCmd* curr_cmd = &CmdBuffer.Data[CmdBuffer.Size - 1];
00544     if (curr_cmd->ElemCount != 0 && curr_cmd->TextureId != _CmdHeader.TextureId)
00545     {
00546         AddDrawCmd();
00547         return;
00548     }
00549     IM_ASSERT(curr_cmd->UserCallback == NULL);
00550 
00551     // Try to merge with previous command if it matches, else use current command
00552     ImDrawCmd* prev_cmd = curr_cmd - 1;
00553     if (curr_cmd->ElemCount == 0 && CmdBuffer.Size > 1 && ImDrawCmd_HeaderCompare(&_CmdHeader, prev_cmd) == 0 && ImDrawCmd_AreSequentialIdxOffset(prev_cmd, curr_cmd) && prev_cmd->UserCallback == NULL)
00554     {
00555         CmdBuffer.pop_back();
00556         return;
00557     }
00558 
00559     curr_cmd->TextureId = _CmdHeader.TextureId;
00560 }
00561 
00562 void ImDrawList::_OnChangedVtxOffset()
00563 {
00564     // We don't need to compare curr_cmd->VtxOffset != _CmdHeader.VtxOffset because we know it'll be different at the time we call this.
00565     _VtxCurrentIdx = 0;
00566     IM_ASSERT_PARANOID(CmdBuffer.Size > 0);
00567     ImDrawCmd* curr_cmd = &CmdBuffer.Data[CmdBuffer.Size - 1];
00568     //IM_ASSERT(curr_cmd->VtxOffset != _CmdHeader.VtxOffset); // See #3349
00569     if (curr_cmd->ElemCount != 0)
00570     {
00571         AddDrawCmd();
00572         return;
00573     }
00574     IM_ASSERT(curr_cmd->UserCallback == NULL);
00575     curr_cmd->VtxOffset = _CmdHeader.VtxOffset;
00576 }
00577 
00578 int ImDrawList::_CalcCircleAutoSegmentCount(float radius) const
00579 {
00580     // Automatic segment count
00581     const int radius_idx = (int)(radius + 0.999999f); // ceil to never reduce accuracy
00582     if (radius_idx >= 0 && radius_idx < IM_ARRAYSIZE(_Data->CircleSegmentCounts))
00583         return _Data->CircleSegmentCounts[radius_idx]; // Use cached value
00584     else
00585         return IM_DRAWLIST_CIRCLE_AUTO_SEGMENT_CALC(radius, _Data->CircleSegmentMaxError);
00586 }
