00588 // Render-level scissoring. This is passed down to your render function but not used for CPU-side coarse clipping. Prefer using higher-level ImGui::PushClipRect() to affect logic (hit-testing and widget culling)
00589 void ImDrawList::PushClipRect(const ImVec2& cr_min, const ImVec2& cr_max, bool intersect_with_current_clip_rect)
00590 {
00591     ImVec4 cr(cr_min.x, cr_min.y, cr_max.x, cr_max.y);
00592     if (intersect_with_current_clip_rect)
00593     {
00594         ImVec4 current = _CmdHeader.ClipRect;
00595         if (cr.x < current.x) cr.x = current.x;
00596         if (cr.y < current.y) cr.y = current.y;
00597         if (cr.z > current.z) cr.z = current.z;
00598         if (cr.w > current.w) cr.w = current.w;
00599     }
00600     cr.z = ImMax(cr.x, cr.z);
00601     cr.w = ImMax(cr.y, cr.w);
00602 
00603     _ClipRectStack.push_back(cr);
00604     _CmdHeader.ClipRect = cr;
00605     _OnChangedClipRect();
00606 }
00607 
00608 void ImDrawList::PushClipRectFullScreen()
00609 {
00610     PushClipRect(ImVec2(_Data->ClipRectFullscreen.x, _Data->ClipRectFullscreen.y), ImVec2(_Data->ClipRectFullscreen.z, _Data->ClipRectFullscreen.w));
00611 }
