00613 void ImDrawList::PopClipRect()
00614 {
00615     _ClipRectStack.pop_back();
00616     _CmdHeader.ClipRect = (_ClipRectStack.Size == 0) ? _Data->ClipRectFullscreen : _ClipRectStack.Data[_ClipRectStack.Size - 1];
00617     _OnChangedClipRect();
00618 }
