00629     _TextureIdStack.pop_back();
00630     _CmdHeader.TextureId = (_TextureIdStack.Size == 0) ? (ImTextureID)NULL : _TextureIdStack.Data[_TextureIdStack.Size - 1];
00631     _OnChangedTextureID();
00632 }
