00634 // Reserve space for a number of vertices and indices.
00635 // You must finish filling your reserved data before calling PrimReserve() again, as it may reallocate or
00636 // submit the intermediate results. PrimUnreserve() can be used to release unused allocations.
00637 void ImDrawList::PrimReserve(int idx_count, int vtx_count)
00638 {
00639     // Large mesh support (when enabled)
00640     IM_ASSERT_PARANOID(idx_count >= 0 && vtx_count >= 0);
00641     if (sizeof(ImDrawIdx) == 2 && (_VtxCurrentIdx + vtx_count >= (1 << 16)) && (Flags & ImDrawListFlags_AllowVtxOffset))
00642     {
00643         // FIXME: In theory we should be testing that vtx_count <64k here.
00644         // In practice, RenderText() relies on reserving ahead for a worst case scenario so it is currently useful for us
00645         // to not make that check until we rework the text functions to handle clipping and large horizontal lines better.
00646         _CmdHeader.VtxOffset = VtxBuffer.Size;
00647         _OnChangedVtxOffset();
00648     }
00649 
00650     ImDrawCmd* draw_cmd = &CmdBuffer.Data[CmdBuffer.Size - 1];
00651     draw_cmd->ElemCount += idx_count;
00652 
00653     int vtx_buffer_old_size = VtxBuffer.Size;
00654     VtxBuffer.resize(vtx_buffer_old_size + vtx_count);
00655     _VtxWritePtr = VtxBuffer.Data + vtx_buffer_old_size;
00656 
00657     int idx_buffer_old_size = IdxBuffer.Size;
00658     IdxBuffer.resize(idx_buffer_old_size + idx_count);
00659     _IdxWritePtr = IdxBuffer.Data + idx_buffer_old_size;
00660 }
00661 
00662 // Release the number of reserved vertices/indices from the end of the last reservation made with PrimReserve().
00663 void ImDrawList::PrimUnreserve(int idx_count, int vtx_count)
00664 {
00665     IM_ASSERT_PARANOID(idx_count >= 0 && vtx_count >= 0);
00666 
00667     ImDrawCmd* draw_cmd = &CmdBuffer.Data[CmdBuffer.Size - 1];
00668     draw_cmd->ElemCount -= idx_count;
00669     VtxBuffer.shrink(VtxBuffer.Size - vtx_count);
00670     IdxBuffer.shrink(IdxBuffer.Size - idx_count);
00671 }
00672 
00673 // Fully unrolled with inline call to keep our debug builds decently fast.
00674 void ImDrawList::PrimRect(const ImVec2& a, const ImVec2& c, ImU32 col)
00675 {
00676     ImVec2 b(c.x, a.y), d(a.x, c.y), uv(_Data->TexUvWhitePixel);
00677     ImDrawIdx idx = (ImDrawIdx)_VtxCurrentIdx;
00678     _IdxWritePtr[0] = idx; _IdxWritePtr[1] = (ImDrawIdx)(idx+1); _IdxWritePtr[2] = (ImDrawIdx)(idx+2);
00679     _IdxWritePtr[3] = idx; _IdxWritePtr[4] = (ImDrawIdx)(idx+2); _IdxWritePtr[5] = (ImDrawIdx)(idx+3);
00680     _VtxWritePtr[0].pos = a; _VtxWritePtr[0].uv = uv; _VtxWritePtr[0].col = col;
00681     _VtxWritePtr[1].pos = b; _VtxWritePtr[1].uv = uv; _VtxWritePtr[1].col = col;
00682     _VtxWritePtr[2].pos = c; _VtxWritePtr[2].uv = uv; _VtxWritePtr[2].col = col;
00683     _VtxWritePtr[3].pos = d; _VtxWritePtr[3].uv = uv; _VtxWritePtr[3].col = col;
00684     _VtxWritePtr += 4;
00685     _VtxCurrentIdx += 4;
00686     _IdxWritePtr += 6;
00687 }
00688 
00689 void ImDrawList::PrimRectUV(const ImVec2& a, const ImVec2& c, const ImVec2& uv_a, const ImVec2& uv_c, ImU32 col)
00690 {
00691     ImVec2 b(c.x, a.y), d(a.x, c.y), uv_b(uv_c.x, uv_a.y), uv_d(uv_a.x, uv_c.y);
00692     ImDrawIdx idx = (ImDrawIdx)_VtxCurrentIdx;
00693     _IdxWritePtr[0] = idx; _IdxWritePtr[1] = (ImDrawIdx)(idx+1); _IdxWritePtr[2] = (ImDrawIdx)(idx+2);
00694     _IdxWritePtr[3] = idx; _IdxWritePtr[4] = (ImDrawIdx)(idx+2); _IdxWritePtr[5] = (ImDrawIdx)(idx+3);
00695     _VtxWritePtr[0].pos = a; _VtxWritePtr[0].uv = uv_a; _VtxWritePtr[0].col = col;
00696     _VtxWritePtr[1].pos = b; _VtxWritePtr[1].uv = uv_b; _VtxWritePtr[1].col = col;
00697     _VtxWritePtr[2].pos = c; _VtxWritePtr[2].uv = uv_c; _VtxWritePtr[2].col = col;
00698     _VtxWritePtr[3].pos = d; _VtxWritePtr[3].uv = uv_d; _VtxWritePtr[3].col = col;
00699     _VtxWritePtr += 4;
00700     _VtxCurrentIdx += 4;
00701     _IdxWritePtr += 6;
00702 }
00703 
00704 void ImDrawList::PrimQuadUV(const ImVec2& a, const ImVec2& b, const ImVec2& c, const ImVec2& d, const ImVec2& uv_a, const ImVec2& uv_b, const ImVec2& uv_c, const ImVec2& uv_d, ImU32 col)
00705 {
00706     ImDrawIdx idx = (ImDrawIdx)_VtxCurrentIdx;
00707     _IdxWritePtr[0] = idx; _IdxWritePtr[1] = (ImDrawIdx)(idx+1); _IdxWritePtr[2] = (ImDrawIdx)(idx+2);
00708     _IdxWritePtr[3] = idx; _IdxWritePtr[4] = (ImDrawIdx)(idx+2); _IdxWritePtr[5] = (ImDrawIdx)(idx+3);
00709     _VtxWritePtr[0].pos = a; _VtxWritePtr[0].uv = uv_a; _VtxWritePtr[0].col = col;
00710     _VtxWritePtr[1].pos = b; _VtxWritePtr[1].uv = uv_b; _VtxWritePtr[1].col = col;
00711     _VtxWritePtr[2].pos = c; _VtxWritePtr[2].uv = uv_c; _VtxWritePtr[2].col = col;
00712     _VtxWritePtr[3].pos = d; _VtxWritePtr[3].uv = uv_d; _VtxWritePtr[3].col = col;
00713     _VtxWritePtr += 4;
00714     _VtxCurrentIdx += 4;
00715     _IdxWritePtr += 6;
00716 }
00717 
00718 // On AddPolyline() and AddConvexPolyFilled() we intentionally avoid using ImVec2 and superfluous function calls to optimize debug/non-inlined builds.
00719 // - Those macros expects l-values and need to be used as their own statement.
00720 // - Those macros are intentionally not surrounded by the 'do {} while (0)' idiom because even that translates to runtime with debug compilers.
00721 #define IM_NORMALIZE2F_OVER_ZERO(VX,VY)     { float d2 = VX*VX + VY*VY; if (d2 > 0.0f) { float inv_len = ImRsqrt(d2); VX *= inv_len; VY *= inv_len; } } (void)0
00722 #define IM_FIXNORMAL2F_MAX_INVLEN2          100.0f // 500.0f (see #4053, #3366)
00723 #define IM_FIXNORMAL2F(VX,VY)               { float d2 = VX*VX + VY*VY; if (d2 > 0.000001f) { float inv_len2 = 1.0f / d2; if (inv_len2 > IM_FIXNORMAL2F_MAX_INVLEN2) inv_len2 = IM_FIXNORMAL2F_MAX_INVLEN2; VX *= inv_len2; VY *= inv_len2; } } (void)0
00724 
00725 // TODO: Thickness anti-aliased lines cap are missing their AA fringe.
00726 // We avoid using the ImVec2 math operators here to reduce cost to a minimum for debug/non-inlined builds.
00727 void ImDrawList::AddPolyline(const ImVec2* points, const int points_count, ImU32 col, ImDrawFlags flags, float thickness)
00728 {
00729     if (points_count < 2 || (col & IM_COL32_A_MASK) == 0)
00730         return;
00731 
00732     const bool closed = (flags & ImDrawFlags_Closed) != 0;
00733     const ImVec2 opaque_uv = _Data->TexUvWhitePixel;
00734     const int count = closed ? points_count : points_count - 1; // The number of line segments we need to draw
00735     const bool thick_line = (thickness > _FringeScale);
00736 
00737     if (Flags & ImDrawListFlags_AntiAliasedLines)
00738     {
00739         // Anti-aliased stroke
00740         const float AA_SIZE = _FringeScale;
00741         const ImU32 col_trans = col & ~IM_COL32_A_MASK;
00742 
00743         // Thicknesses <1.0 should behave like thickness 1.0
00744         thickness = ImMax(thickness, 1.0f);
00745         const int integer_thickness = (int)thickness;
00746         const float fractional_thickness = thickness - integer_thickness;
00747 
00748         // Do we want to draw this line using a texture?
00749         // - For now, only draw integer-width lines using textures to avoid issues with the way scaling occurs, could be improved.
00750         // - If AA_SIZE is not 1.0f we cannot use the texture path.
00751         const bool use_texture = (Flags & ImDrawListFlags_AntiAliasedLinesUseTex) && (integer_thickness < IM_DRAWLIST_TEX_LINES_WIDTH_MAX) && (fractional_thickness <= 0.00001f) && (AA_SIZE == 1.0f);
00752 
00753         // We should never hit this, because NewFrame() doesn't set ImDrawListFlags_AntiAliasedLinesUseTex unless ImFontAtlasFlags_NoBakedLines is off
00754         IM_ASSERT_PARANOID(!use_texture || !(_Data->Font->ContainerAtlas->Flags & ImFontAtlasFlags_NoBakedLines));
00755 
00756         const int idx_count = use_texture ? (count * 6) : (thick_line ? count * 18 : count * 12);
00757         const int vtx_count = use_texture ? (points_count * 2) : (thick_line ? points_count * 4 : points_count * 3);
00758         PrimReserve(idx_count, vtx_count);
00759 
00760         // Temporary buffer
00761         // The first <points_count> items are normals at each line point, then after that there are either 2 or 4 temp points for each line point
00762         _Data->TempBuffer.reserve_discard(points_count * ((use_texture || !thick_line) ? 3 : 5));
00763         ImVec2* temp_normals = _Data->TempBuffer.Data;
00764         ImVec2* temp_points = temp_normals + points_count;
00765 
00766         // Calculate normals (tangents) for each line segment
00767         for (int i1 = 0; i1 < count; i1++)
00768         {
00769             const int i2 = (i1 + 1) == points_count ? 0 : i1 + 1;
00770             float dx = points[i2].x - points[i1].x;
00771             float dy = points[i2].y - points[i1].y;
00772             IM_NORMALIZE2F_OVER_ZERO(dx, dy);
00773             temp_normals[i1].x = dy;
00774             temp_normals[i1].y = -dx;
00775         }
00776         if (!closed)
00777             temp_normals[points_count - 1] = temp_normals[points_count - 2];
00778 
00779         // If we are drawing a one-pixel-wide line without a texture, or a textured line of any width, we only need 2 or 3 vertices per point
00780         if (use_texture || !thick_line)
00781         {
00782             // [PATH 1] Texture-based lines (thick or non-thick)
00783             // [PATH 2] Non texture-based lines (non-thick)
00784 
00785             // The width of the geometry we need to draw - this is essentially <thickness> pixels for the line itself, plus "one pixel" for AA.
00786             // - In the texture-based path, we don't use AA_SIZE here because the +1 is tied to the generated texture
00787             //   (see ImFontAtlasBuildRenderLinesTexData() function), and so alternate values won't work without changes to that code.
00788             // - In the non texture-based paths, we would allow AA_SIZE to potentially be != 1.0f with a patch (e.g. fringe_scale patch to
00789             //   allow scaling geometry while preserving one-screen-pixel AA fringe).
00790             const float half_draw_size = use_texture ? ((thickness * 0.5f) + 1) : AA_SIZE;
00791 
00792             // If line is not closed, the first and last points need to be generated differently as there are no normals to blend
00793             if (!closed)
00794             {
00795                 temp_points[0] = points[0] + temp_normals[0] * half_draw_size;
00796                 temp_points[1] = points[0] - temp_normals[0] * half_draw_size;
00797                 temp_points[(points_count-1)*2+0] = points[points_count-1] + temp_normals[points_count-1] * half_draw_size;
00798                 temp_points[(points_count-1)*2+1] = points[points_count-1] - temp_normals[points_count-1] * half_draw_size;
00799             }
00800 
00801             // Generate the indices to form a number of triangles for each line segment, and the vertices for the line edges
00802             // This takes points n and n+1 and writes into n+1, with the first point in a closed line being generated from the final one (as n+1 wraps)
00803             // FIXME-OPT: Merge the different loops, possibly remove the temporary buffer.
00804             unsigned int idx1 = _VtxCurrentIdx; // Vertex index for start of line segment
00805             for (int i1 = 0; i1 < count; i1++) // i1 is the first point of the line segment
00806             {
00807                 const int i2 = (i1 + 1) == points_count ? 0 : i1 + 1; // i2 is the second point of the line segment
00808                 const unsigned int idx2 = ((i1 + 1) == points_count) ? _VtxCurrentIdx : (idx1 + (use_texture ? 2 : 3)); // Vertex index for end of segment
00809 
00810                 // Average normals
00811                 float dm_x = (temp_normals[i1].x + temp_normals[i2].x) * 0.5f;
00812                 float dm_y = (temp_normals[i1].y + temp_normals[i2].y) * 0.5f;
00813                 IM_FIXNORMAL2F(dm_x, dm_y);
00814                 dm_x *= half_draw_size; // dm_x, dm_y are offset to the outer edge of the AA area
00815                 dm_y *= half_draw_size;
00816 
00817                 // Add temporary vertexes for the outer edges
00818                 ImVec2* out_vtx = &temp_points[i2 * 2];
00819                 out_vtx[0].x = points[i2].x + dm_x;
00820                 out_vtx[0].y = points[i2].y + dm_y;
00821                 out_vtx[1].x = points[i2].x - dm_x;
00822                 out_vtx[1].y = points[i2].y - dm_y;
00823 
00824                 if (use_texture)
00825                 {
00826                     // Add indices for two triangles
00827                     _IdxWritePtr[0] = (ImDrawIdx)(idx2 + 0); _IdxWritePtr[1] = (ImDrawIdx)(idx1 + 0); _IdxWritePtr[2] = (ImDrawIdx)(idx1 + 1); // Right tri
00828                     _IdxWritePtr[3] = (ImDrawIdx)(idx2 + 1); _IdxWritePtr[4] = (ImDrawIdx)(idx1 + 1); _IdxWritePtr[5] = (ImDrawIdx)(idx2 + 0); // Left tri
00829                     _IdxWritePtr += 6;
00830                 }
00831                 else
00832                 {
00833                     // Add indexes for four triangles
00834                     _IdxWritePtr[0] = (ImDrawIdx)(idx2 + 0); _IdxWritePtr[1] = (ImDrawIdx)(idx1 + 0); _IdxWritePtr[2] = (ImDrawIdx)(idx1 + 2); // Right tri 1
00835                     _IdxWritePtr[3] = (ImDrawIdx)(idx1 + 2); _IdxWritePtr[4] = (ImDrawIdx)(idx2 + 2); _IdxWritePtr[5] = (ImDrawIdx)(idx2 + 0); // Right tri 2
00836                     _IdxWritePtr[6] = (ImDrawIdx)(idx2 + 1); _IdxWritePtr[7] = (ImDrawIdx)(idx1 + 1); _IdxWritePtr[8] = (ImDrawIdx)(idx1 + 0); // Left tri 1
00837                     _IdxWritePtr[9] = (ImDrawIdx)(idx1 + 0); _IdxWritePtr[10] = (ImDrawIdx)(idx2 + 0); _IdxWritePtr[11] = (ImDrawIdx)(idx2 + 1); // Left tri 2
00838                     _IdxWritePtr += 12;
00839                 }
00840 
00841                 idx1 = idx2;
00842             }
00843 
00844             // Add vertexes for each point on the line
00845             if (use_texture)
00846             {
00847                 // If we're using textures we only need to emit the left/right edge vertices
00848                 ImVec4 tex_uvs = _Data->TexUvLines[integer_thickness];
00849                 /*if (fractional_thickness != 0.0f) // Currently always zero when use_texture==false!
00850                 {
00851                     const ImVec4 tex_uvs_1 = _Data->TexUvLines[integer_thickness + 1];
00852                     tex_uvs.x = tex_uvs.x + (tex_uvs_1.x - tex_uvs.x) * fractional_thickness; // inlined ImLerp()
00853                     tex_uvs.y = tex_uvs.y + (tex_uvs_1.y - tex_uvs.y) * fractional_thickness;
00854                     tex_uvs.z = tex_uvs.z + (tex_uvs_1.z - tex_uvs.z) * fractional_thickness;
00855                     tex_uvs.w = tex_uvs.w + (tex_uvs_1.w - tex_uvs.w) * fractional_thickness;
00856                 }*/
00857                 ImVec2 tex_uv0(tex_uvs.x, tex_uvs.y);
00858                 ImVec2 tex_uv1(tex_uvs.z, tex_uvs.w);
00859                 for (int i = 0; i < points_count; i++)
00860                 {
00861                     _VtxWritePtr[0].pos = temp_points[i * 2 + 0]; _VtxWritePtr[0].uv = tex_uv0; _VtxWritePtr[0].col = col; // Left-side outer edge
00862                     _VtxWritePtr[1].pos = temp_points[i * 2 + 1]; _VtxWritePtr[1].uv = tex_uv1; _VtxWritePtr[1].col = col; // Right-side outer edge
00863                     _VtxWritePtr += 2;
00864                 }
00865             }
00866             else
00867             {
00868                 // If we're not using a texture, we need the center vertex as well
00869                 for (int i = 0; i < points_count; i++)
00870                 {
00871                     _VtxWritePtr[0].pos = points[i];              _VtxWritePtr[0].uv = opaque_uv; _VtxWritePtr[0].col = col;       // Center of line
00872                     _VtxWritePtr[1].pos = temp_points[i * 2 + 0]; _VtxWritePtr[1].uv = opaque_uv; _VtxWritePtr[1].col = col_trans; // Left-side outer edge
00873                     _VtxWritePtr[2].pos = temp_points[i * 2 + 1]; _VtxWritePtr[2].uv = opaque_uv; _VtxWritePtr[2].col = col_trans; // Right-side outer edge
00874                     _VtxWritePtr += 3;
00875                 }
00876             }
00877         }
00878         else
00879         {
00880             // [PATH 2] Non texture-based lines (thick): we need to draw the solid line core and thus require four vertices per point
00881             const float half_inner_thickness = (thickness - AA_SIZE) * 0.5f;
00882 
00883             // If line is not closed, the first and last points need to be generated differently as there are no normals to blend
00884             if (!closed)
00885             {
00886                 const int points_last = points_count - 1;
00887                 temp_points[0] = points[0] + temp_normals[0] * (half_inner_thickness + AA_SIZE);
00888                 temp_points[1] = points[0] + temp_normals[0] * (half_inner_thickness);
00889                 temp_points[2] = points[0] - temp_normals[0] * (half_inner_thickness);
00890                 temp_points[3] = points[0] - temp_normals[0] * (half_inner_thickness + AA_SIZE);
00891                 temp_points[points_last * 4 + 0] = points[points_last] + temp_normals[points_last] * (half_inner_thickness + AA_SIZE);
00892                 temp_points[points_last * 4 + 1] = points[points_last] + temp_normals[points_last] * (half_inner_thickness);
00893                 temp_points[points_last * 4 + 2] = points[points_last] - temp_normals[points_last] * (half_inner_thickness);
00894                 temp_points[points_last * 4 + 3] = points[points_last] - temp_normals[points_last] * (half_inner_thickness + AA_SIZE);
00895             }
00896 
00897             // Generate the indices to form a number of triangles for each line segment, and the vertices for the line edges
00898             // This takes points n and n+1 and writes into n+1, with the first point in a closed line being generated from the final one (as n+1 wraps)
00899             // FIXME-OPT: Merge the different loops, possibly remove the temporary buffer.
00900             unsigned int idx1 = _VtxCurrentIdx; // Vertex index for start of line segment
00901             for (int i1 = 0; i1 < count; i1++) // i1 is the first point of the line segment
00902             {
00903                 const int i2 = (i1 + 1) == points_count ? 0 : (i1 + 1); // i2 is the second point of the line segment
00904                 const unsigned int idx2 = (i1 + 1) == points_count ? _VtxCurrentIdx : (idx1 + 4); // Vertex index for end of segment
00905 
00906                 // Average normals
00907                 float dm_x = (temp_normals[i1].x + temp_normals[i2].x) * 0.5f;
00908                 float dm_y = (temp_normals[i1].y + temp_normals[i2].y) * 0.5f;
00909                 IM_FIXNORMAL2F(dm_x, dm_y);
00910                 float dm_out_x = dm_x * (half_inner_thickness + AA_SIZE);
00911                 float dm_out_y = dm_y * (half_inner_thickness + AA_SIZE);
00912                 float dm_in_x = dm_x * half_inner_thickness;
00913                 float dm_in_y = dm_y * half_inner_thickness;
00914 
00915                 // Add temporary vertices
00916                 ImVec2* out_vtx = &temp_points[i2 * 4];
00917                 out_vtx[0].x = points[i2].x + dm_out_x;
00918                 out_vtx[0].y = points[i2].y + dm_out_y;
00919                 out_vtx[1].x = points[i2].x + dm_in_x;
00920                 out_vtx[1].y = points[i2].y + dm_in_y;
00921                 out_vtx[2].x = points[i2].x - dm_in_x;
00922                 out_vtx[2].y = points[i2].y - dm_in_y;
00923                 out_vtx[3].x = points[i2].x - dm_out_x;
00924                 out_vtx[3].y = points[i2].y - dm_out_y;
00925 
00926                 // Add indexes
00927                 _IdxWritePtr[0]  = (ImDrawIdx)(idx2 + 1); _IdxWritePtr[1]  = (ImDrawIdx)(idx1 + 1); _IdxWritePtr[2]  = (ImDrawIdx)(idx1 + 2);
00928                 _IdxWritePtr[3]  = (ImDrawIdx)(idx1 + 2); _IdxWritePtr[4]  = (ImDrawIdx)(idx2 + 2); _IdxWritePtr[5]  = (ImDrawIdx)(idx2 + 1);
00929                 _IdxWritePtr[6]  = (ImDrawIdx)(idx2 + 1); _IdxWritePtr[7]  = (ImDrawIdx)(idx1 + 1); _IdxWritePtr[8]  = (ImDrawIdx)(idx1 + 0);
00930                 _IdxWritePtr[9]  = (ImDrawIdx)(idx1 + 0); _IdxWritePtr[10] = (ImDrawIdx)(idx2 + 0); _IdxWritePtr[11] = (ImDrawIdx)(idx2 + 1);
00931                 _IdxWritePtr[12] = (ImDrawIdx)(idx2 + 2); _IdxWritePtr[13] = (ImDrawIdx)(idx1 + 2); _IdxWritePtr[14] = (ImDrawIdx)(idx1 + 3);
00932                 _IdxWritePtr[15] = (ImDrawIdx)(idx1 + 3); _IdxWritePtr[16] = (ImDrawIdx)(idx2 + 3); _IdxWritePtr[17] = (ImDrawIdx)(idx2 + 2);
00933                 _IdxWritePtr += 18;
00934 
00935                 idx1 = idx2;
00936             }
00937 
00938             // Add vertices
00939             for (int i = 0; i < points_count; i++)
00940             {
00941                 _VtxWritePtr[0].pos = temp_points[i * 4 + 0]; _VtxWritePtr[0].uv = opaque_uv; _VtxWritePtr[0].col = col_trans;
00942                 _VtxWritePtr[1].pos = temp_points[i * 4 + 1]; _VtxWritePtr[1].uv = opaque_uv; _VtxWritePtr[1].col = col;
00943                 _VtxWritePtr[2].pos = temp_points[i * 4 + 2]; _VtxWritePtr[2].uv = opaque_uv; _VtxWritePtr[2].col = col;
00944                 _VtxWritePtr[3].pos = temp_points[i * 4 + 3]; _VtxWritePtr[3].uv = opaque_uv; _VtxWritePtr[3].col = col_trans;
00945                 _VtxWritePtr += 4;
00946             }
00947         }
00948         _VtxCurrentIdx += (ImDrawIdx)vtx_count;
00949     }
00950     else
00951     {
00952         // [PATH 4] Non texture-based, Non anti-aliased lines
00953         const int idx_count = count * 6;
00954         const int vtx_count = count * 4;    // FIXME-OPT: Not sharing edges
00955         PrimReserve(idx_count, vtx_count);
00956 
00957         for (int i1 = 0; i1 < count; i1++)
00958         {
00959             const int i2 = (i1 + 1) == points_count ? 0 : i1 + 1;
00960             const ImVec2& p1 = points[i1];
00961             const ImVec2& p2 = points[i2];
00962 
00963             float dx = p2.x - p1.x;
00964             float dy = p2.y - p1.y;
00965             IM_NORMALIZE2F_OVER_ZERO(dx, dy);
00966             dx *= (thickness * 0.5f);
00967             dy *= (thickness * 0.5f);
00968 
00969             _VtxWritePtr[0].pos.x = p1.x + dy; _VtxWritePtr[0].pos.y = p1.y - dx; _VtxWritePtr[0].uv = opaque_uv; _VtxWritePtr[0].col = col;
00970             _VtxWritePtr[1].pos.x = p2.x + dy; _VtxWritePtr[1].pos.y = p2.y - dx; _VtxWritePtr[1].uv = opaque_uv; _VtxWritePtr[1].col = col;
00971             _VtxWritePtr[2].pos.x = p2.x - dy; _VtxWritePtr[2].pos.y = p2.y + dx; _VtxWritePtr[2].uv = opaque_uv; _VtxWritePtr[2].col = col;
00972             _VtxWritePtr[3].pos.x = p1.x - dy; _VtxWritePtr[3].pos.y = p1.y + dx; _VtxWritePtr[3].uv = opaque_uv; _VtxWritePtr[3].col = col;
00973             _VtxWritePtr += 4;
00974 
00975             _IdxWritePtr[0] = (ImDrawIdx)(_VtxCurrentIdx); _IdxWritePtr[1] = (ImDrawIdx)(_VtxCurrentIdx + 1); _IdxWritePtr[2] = (ImDrawIdx)(_VtxCurrentIdx + 2);
00976             _IdxWritePtr[3] = (ImDrawIdx)(_VtxCurrentIdx); _IdxWritePtr[4] = (ImDrawIdx)(_VtxCurrentIdx + 2); _IdxWritePtr[5] = (ImDrawIdx)(_VtxCurrentIdx + 3);
00977             _IdxWritePtr += 6;
00978             _VtxCurrentIdx += 4;
00979         }
00980     }
00981 }
00982 
00983 // - We intentionally avoid using ImVec2 and its math operators here to reduce cost to a minimum for debug/non-inlined builds.
00984 // - Filled shapes must always use clockwise winding order. The anti-aliasing fringe depends on it. Counter-clockwise shapes will have "inward" anti-aliasing.
00985 void ImDrawList::AddConvexPolyFilled(const ImVec2* points, const int points_count, ImU32 col)
00986 {
00987     if (points_count < 3 || (col & IM_COL32_A_MASK) == 0)
00988         return;
00989 
00990     const ImVec2 uv = _Data->TexUvWhitePixel;
00991 
00992     if (Flags & ImDrawListFlags_AntiAliasedFill)
00993     {
00994         // Anti-aliased Fill
00995         const float AA_SIZE = _FringeScale;
00996         const ImU32 col_trans = col & ~IM_COL32_A_MASK;
00997         const int idx_count = (points_count - 2)*3 + points_count * 6;
00998         const int vtx_count = (points_count * 2);
00999         PrimReserve(idx_count, vtx_count);
01000 
01001         // Add indexes for fill
01002         unsigned int vtx_inner_idx = _VtxCurrentIdx;
01003         unsigned int vtx_outer_idx = _VtxCurrentIdx + 1;
01004         for (int i = 2; i < points_count; i++)
01005         {
01006             _IdxWritePtr[0] = (ImDrawIdx)(vtx_inner_idx); _IdxWritePtr[1] = (ImDrawIdx)(vtx_inner_idx + ((i - 1) << 1)); _IdxWritePtr[2] = (ImDrawIdx)(vtx_inner_idx + (i << 1));
01007             _IdxWritePtr += 3;
01008         }
01009 
01010         // Compute normals
01011         _Data->TempBuffer.reserve_discard(points_count);
01012         ImVec2* temp_normals = _Data->TempBuffer.Data;
01013         for (int i0 = points_count - 1, i1 = 0; i1 < points_count; i0 = i1++)
01014         {
01015             const ImVec2& p0 = points[i0];
01016             const ImVec2& p1 = points[i1];
01017             float dx = p1.x - p0.x;
01018             float dy = p1.y - p0.y;
01019             IM_NORMALIZE2F_OVER_ZERO(dx, dy);
01020             temp_normals[i0].x = dy;
01021             temp_normals[i0].y = -dx;
01022         }
01023 
01024         for (int i0 = points_count - 1, i1 = 0; i1 < points_count; i0 = i1++)
01025         {
01026             // Average normals
01027             const ImVec2& n0 = temp_normals[i0];
01028             const ImVec2& n1 = temp_normals[i1];
01029             float dm_x = (n0.x + n1.x) * 0.5f;
01030             float dm_y = (n0.y + n1.y) * 0.5f;
01031             IM_FIXNORMAL2F(dm_x, dm_y);
01032             dm_x *= AA_SIZE * 0.5f;
01033             dm_y *= AA_SIZE * 0.5f;
01034 
01035             // Add vertices
01036             _VtxWritePtr[0].pos.x = (points[i1].x - dm_x); _VtxWritePtr[0].pos.y = (points[i1].y - dm_y); _VtxWritePtr[0].uv = uv; _VtxWritePtr[0].col = col;        // Inner
01037             _VtxWritePtr[1].pos.x = (points[i1].x + dm_x); _VtxWritePtr[1].pos.y = (points[i1].y + dm_y); _VtxWritePtr[1].uv = uv; _VtxWritePtr[1].col = col_trans;  // Outer
01038             _VtxWritePtr += 2;
01039 
01040             // Add indexes for fringes
01041             _IdxWritePtr[0] = (ImDrawIdx)(vtx_inner_idx + (i1 << 1)); _IdxWritePtr[1] = (ImDrawIdx)(vtx_inner_idx + (i0 << 1)); _IdxWritePtr[2] = (ImDrawIdx)(vtx_outer_idx + (i0 << 1));
01042             _IdxWritePtr[3] = (ImDrawIdx)(vtx_outer_idx + (i0 << 1)); _IdxWritePtr[4] = (ImDrawIdx)(vtx_outer_idx + (i1 << 1)); _IdxWritePtr[5] = (ImDrawIdx)(vtx_inner_idx + (i1 << 1));
01043             _IdxWritePtr += 6;
01044         }
01045         _VtxCurrentIdx += (ImDrawIdx)vtx_count;
01046     }
01047     else
01048     {
01049         // Non Anti-aliased Fill
01050         const int idx_count = (points_count - 2)*3;
01051         const int vtx_count = points_count;
01052         PrimReserve(idx_count, vtx_count);
01053         for (int i = 0; i < vtx_count; i++)
01054         {
01055             _VtxWritePtr[0].pos = points[i]; _VtxWritePtr[0].uv = uv; _VtxWritePtr[0].col = col;
01056             _VtxWritePtr++;
01057         }
01058         for (int i = 2; i < points_count; i++)
01059         {
01060             _IdxWritePtr[0] = (ImDrawIdx)(_VtxCurrentIdx); _IdxWritePtr[1] = (ImDrawIdx)(_VtxCurrentIdx + i - 1); _IdxWritePtr[2] = (ImDrawIdx)(_VtxCurrentIdx + i);
01061             _IdxWritePtr += 3;
01062         }
01063         _VtxCurrentIdx += (ImDrawIdx)vtx_count;
01064     }
01065 }
01066 
01067 void ImDrawList::_PathArcToFastEx(const ImVec2& center, float radius, int a_min_sample, int a_max_sample, int a_step)
01068 {
01069     if (radius < 0.5f)
01070     {
01071         _Path.push_back(center);
01072         return;
01073     }
01074 
01075     // Calculate arc auto segment step size
01076     if (a_step <= 0)
01077         a_step = IM_DRAWLIST_ARCFAST_SAMPLE_MAX / _CalcCircleAutoSegmentCount(radius);
01078 
01079     // Make sure we never do steps larger than one quarter of the circle
01080     a_step = ImClamp(a_step, 1, IM_DRAWLIST_ARCFAST_TABLE_SIZE / 4);
01081 
01082     const int sample_range = ImAbs(a_max_sample - a_min_sample);
01083     const int a_next_step = a_step;
01084 
01085     int samples = sample_range + 1;
01086     bool extra_max_sample = false;
01087     if (a_step > 1)
01088     {
01089         samples            = sample_range / a_step + 1;
01090         const int overstep = sample_range % a_step;
01091 
01092         if (overstep > 0)
01093         {
01094             extra_max_sample = true;
01095             samples++;
01096 
01097             // When we have overstep to avoid awkwardly looking one long line and one tiny one at the end,
01098             // distribute first step range evenly between them by reducing first step size.
01099             if (sample_range > 0)
01100                 a_step -= (a_step - overstep) / 2;
01101         }
01102     }
01103 
01104     _Path.resize(_Path.Size + samples);
01105     ImVec2* out_ptr = _Path.Data + (_Path.Size - samples);
01106 
01107     int sample_index = a_min_sample;
01108     if (sample_index < 0 || sample_index >= IM_DRAWLIST_ARCFAST_SAMPLE_MAX)
01109     {
01110         sample_index = sample_index % IM_DRAWLIST_ARCFAST_SAMPLE_MAX;
01111         if (sample_index < 0)
01112             sample_index += IM_DRAWLIST_ARCFAST_SAMPLE_MAX;
01113     }
01114 
01115     if (a_max_sample >= a_min_sample)
01116     {
01117         for (int a = a_min_sample; a <= a_max_sample; a += a_step, sample_index += a_step, a_step = a_next_step)
01118         {
01119             // a_step is clamped to IM_DRAWLIST_ARCFAST_SAMPLE_MAX, so we have guaranteed that it will not wrap over range twice or more
01120             if (sample_index >= IM_DRAWLIST_ARCFAST_SAMPLE_MAX)
01121                 sample_index -= IM_DRAWLIST_ARCFAST_SAMPLE_MAX;
01122 
01123             const ImVec2 s = _Data->ArcFastVtx[sample_index];
01124             out_ptr->x = center.x + s.x * radius;
01125             out_ptr->y = center.y + s.y * radius;
01126             out_ptr++;
01127         }
01128     }
01129     else
01130     {
01131         for (int a = a_min_sample; a >= a_max_sample; a -= a_step, sample_index -= a_step, a_step = a_next_step)
01132         {
01133             // a_step is clamped to IM_DRAWLIST_ARCFAST_SAMPLE_MAX, so we have guaranteed that it will not wrap over range twice or more
01134             if (sample_index < 0)
01135                 sample_index += IM_DRAWLIST_ARCFAST_SAMPLE_MAX;
01136 
01137             const ImVec2 s = _Data->ArcFastVtx[sample_index];
01138             out_ptr->x = center.x + s.x * radius;
01139             out_ptr->y = center.y + s.y * radius;
01140             out_ptr++;
01141         }
01142     }
01143 
01144     if (extra_max_sample)
01145     {
01146         int normalized_max_sample = a_max_sample % IM_DRAWLIST_ARCFAST_SAMPLE_MAX;
01147         if (normalized_max_sample < 0)
01148             normalized_max_sample += IM_DRAWLIST_ARCFAST_SAMPLE_MAX;
01149 
01150         const ImVec2 s = _Data->ArcFastVtx[normalized_max_sample];
01151         out_ptr->x = center.x + s.x * radius;
01152         out_ptr->y = center.y + s.y * radius;
01153         out_ptr++;
01154     }
01155 
01156     IM_ASSERT_PARANOID(_Path.Data + _Path.Size == out_ptr);
01157 }
01158 
01159 void ImDrawList::_PathArcToN(const ImVec2& center, float radius, float a_min, float a_max, int num_segments)
01160 {
01161     if (radius < 0.5f)
01162     {
01163         _Path.push_back(center);
01164         return;
01165     }
01166 
01167     // Note that we are adding a point at both a_min and a_max.
01168     // If you are trying to draw a full closed circle you don't want the overlapping points!
01169     _Path.reserve(_Path.Size + (num_segments + 1));
01170     for (int i = 0; i <= num_segments; i++)
01171     {
01172         const float a = a_min + ((float)i / (float)num_segments) * (a_max - a_min);
01173         _Path.push_back(ImVec2(center.x + ImCos(a) * radius, center.y + ImSin(a) * radius));
01174     }
01175 }
01176 
01177 // 0: East, 3: South, 6: West, 9: North, 12: East
01178 void ImDrawList::PathArcToFast(const ImVec2& center, float radius, int a_min_of_12, int a_max_of_12)
01179 {
01180     if (radius < 0.5f)
01181     {
01182         _Path.push_back(center);
01183         return;
01184     }
01185     _PathArcToFastEx(center, radius, a_min_of_12 * IM_DRAWLIST_ARCFAST_SAMPLE_MAX / 12, a_max_of_12 * IM_DRAWLIST_ARCFAST_SAMPLE_MAX / 12, 0);
01186 }
01187 
01188 void ImDrawList::PathArcTo(const ImVec2& center, float radius, float a_min, float a_max, int num_segments)
01189 {
01190     if (radius < 0.5f)
01191     {
01192         _Path.push_back(center);
01193         return;
01194     }
01195 
01196     if (num_segments > 0)
01197     {
01198         _PathArcToN(center, radius, a_min, a_max, num_segments);
01199         return;
01200     }
01201 
01202     // Automatic segment count
01203     if (radius <= _Data->ArcFastRadiusCutoff)
01204     {
01205         const bool a_is_reverse = a_max < a_min;
01206 
01207         // We are going to use precomputed values for mid samples.
01208         // Determine first and last sample in lookup table that belong to the arc.
01209         const float a_min_sample_f = IM_DRAWLIST_ARCFAST_SAMPLE_MAX * a_min / (IM_PI * 2.0f);
01210         const float a_max_sample_f = IM_DRAWLIST_ARCFAST_SAMPLE_MAX * a_max / (IM_PI * 2.0f);
01211 
01212         const int a_min_sample = a_is_reverse ? (int)ImFloor(a_min_sample_f) : (int)ImCeil(a_min_sample_f);
01213         const int a_max_sample = a_is_reverse ? (int)ImCeil(a_max_sample_f) : (int)ImFloor(a_max_sample_f);
01214         const int a_mid_samples = a_is_reverse ? ImMax(a_min_sample - a_max_sample, 0) : ImMax(a_max_sample - a_min_sample, 0);
01215 
01216         const float a_min_segment_angle = a_min_sample * IM_PI * 2.0f / IM_DRAWLIST_ARCFAST_SAMPLE_MAX;
01217         const float a_max_segment_angle = a_max_sample * IM_PI * 2.0f / IM_DRAWLIST_ARCFAST_SAMPLE_MAX;
01218         const bool a_emit_start = ImAbs(a_min_segment_angle - a_min) >= 1e-5f;
01219         const bool a_emit_end = ImAbs(a_max - a_max_segment_angle) >= 1e-5f;
01220 
01221         _Path.reserve(_Path.Size + (a_mid_samples + 1 + (a_emit_start ? 1 : 0) + (a_emit_end ? 1 : 0)));
01222         if (a_emit_start)
01223             _Path.push_back(ImVec2(center.x + ImCos(a_min) * radius, center.y + ImSin(a_min) * radius));
01224         if (a_mid_samples > 0)
01225             _PathArcToFastEx(center, radius, a_min_sample, a_max_sample, 0);
01226         if (a_emit_end)
01227             _Path.push_back(ImVec2(center.x + ImCos(a_max) * radius, center.y + ImSin(a_max) * radius));
01228     }
01229     else
01230     {
01231         const float arc_length = ImAbs(a_max - a_min);
01232         const int circle_segment_count = _CalcCircleAutoSegmentCount(radius);
01233         const int arc_segment_count = ImMax((int)ImCeil(circle_segment_count * arc_length / (IM_PI * 2.0f)), (int)(2.0f * IM_PI / arc_length));
01234         _PathArcToN(center, radius, a_min, a_max, arc_segment_count);
01235     }
01236 }
01237 
01238 void ImDrawList::PathEllipticalArcTo(const ImVec2& center, const ImVec2& radius, float rot, float a_min, float a_max, int num_segments)
01239 {
01240     if (num_segments <= 0)
01241         num_segments = _CalcCircleAutoSegmentCount(ImMax(radius.x, radius.y)); // A bit pessimistic, maybe there's a better computation to do here.
01242 
01243     _Path.reserve(_Path.Size + (num_segments + 1));
01244 
01245     const float cos_rot = ImCos(rot);
01246     const float sin_rot = ImSin(rot);
01247     for (int i = 0; i <= num_segments; i++)
01248     {
01249         const float a = a_min + ((float)i / (float)num_segments) * (a_max - a_min);
01250         ImVec2 point(ImCos(a) * radius.x, ImSin(a) * radius.y);
01251         const ImVec2 rel((point.x * cos_rot) - (point.y * sin_rot), (point.x * sin_rot) + (point.y * cos_rot));
01252         point.x = rel.x + center.x;
01253         point.y = rel.y + center.y;
01254         _Path.push_back(point);
01255     }
01256 }
01257 
01258 ImVec2 ImBezierCubicCalc(const ImVec2& p1, const ImVec2& p2, const ImVec2& p3, const ImVec2& p4, float t)
01259 {
01260     float u = 1.0f - t;
01261     float w1 = u * u * u;
01262     float w2 = 3 * u * u * t;
01263     float w3 = 3 * u * t * t;
01264     float w4 = t * t * t;
01265     return ImVec2(w1 * p1.x + w2 * p2.x + w3 * p3.x + w4 * p4.x, w1 * p1.y + w2 * p2.y + w3 * p3.y + w4 * p4.y);
01266 }
01267 
01268 ImVec2 ImBezierQuadraticCalc(const ImVec2& p1, const ImVec2& p2, const ImVec2& p3, float t)
01269 {
01270     float u = 1.0f - t;
01271     float w1 = u * u;
01272     float w2 = 2 * u * t;
01273     float w3 = t * t;
01274     return ImVec2(w1 * p1.x + w2 * p2.x + w3 * p3.x, w1 * p1.y + w2 * p2.y + w3 * p3.y);
01275 }
01276 
01277 // Closely mimics ImBezierCubicClosestPointCasteljau() in imgui.cpp
01278 static void PathBezierCubicCurveToCasteljau(ImVector<ImVec2>* path, float x1, float y1, float x2, float y2, float x3, float y3, float x4, float y4, float tess_tol, int level)
01279 {
01280     float dx = x4 - x1;
01281     float dy = y4 - y1;
01282     float d2 = (x2 - x4) * dy - (y2 - y4) * dx;
01283     float d3 = (x3 - x4) * dy - (y3 - y4) * dx;
01284     d2 = (d2 >= 0) ? d2 : -d2;
01285     d3 = (d3 >= 0) ? d3 : -d3;
01286     if ((d2 + d3) * (d2 + d3) < tess_tol * (dx * dx + dy * dy))
01287     {
01288         path->push_back(ImVec2(x4, y4));
01289     }
01290     else if (level < 10)
01291     {
01292         float x12 = (x1 + x2) * 0.5f, y12 = (y1 + y2) * 0.5f;
01293         float x23 = (x2 + x3) * 0.5f, y23 = (y2 + y3) * 0.5f;
01294         float x34 = (x3 + x4) * 0.5f, y34 = (y3 + y4) * 0.5f;
01295         float x123 = (x12 + x23) * 0.5f, y123 = (y12 + y23) * 0.5f;
01296         float x234 = (x23 + x34) * 0.5f, y234 = (y23 + y34) * 0.5f;
01297         float x1234 = (x123 + x234) * 0.5f, y1234 = (y123 + y234) * 0.5f;
01298         PathBezierCubicCurveToCasteljau(path, x1, y1, x12, y12, x123, y123, x1234, y1234, tess_tol, level + 1);
01299         PathBezierCubicCurveToCasteljau(path, x1234, y1234, x234, y234, x34, y34, x4, y4, tess_tol, level + 1);
01300     }
01301 }
01302 
01303 static void PathBezierQuadraticCurveToCasteljau(ImVector<ImVec2>* path, float x1, float y1, float x2, float y2, float x3, float y3, float tess_tol, int level)
01304 {
01305     float dx = x3 - x1, dy = y3 - y1;
01306     float det = (x2 - x3) * dy - (y2 - y3) * dx;
01307     if (det * det * 4.0f < tess_tol * (dx * dx + dy * dy))
01308     {
01309         path->push_back(ImVec2(x3, y3));
01310     }
01311     else if (level < 10)
01312     {
01313         float x12 = (x1 + x2) * 0.5f, y12 = (y1 + y2) * 0.5f;
01314         float x23 = (x2 + x3) * 0.5f, y23 = (y2 + y3) * 0.5f;
01315         float x123 = (x12 + x23) * 0.5f, y123 = (y12 + y23) * 0.5f;
01316         PathBezierQuadraticCurveToCasteljau(path, x1, y1, x12, y12, x123, y123, tess_tol, level + 1);
01317         PathBezierQuadraticCurveToCasteljau(path, x123, y123, x23, y23, x3, y3, tess_tol, level + 1);
01318     }
01319 }
01320 
01321 void ImDrawList::PathBezierCubicCurveTo(const ImVec2& p2, const ImVec2& p3, const ImVec2& p4, int num_segments)
01322 {
01323     ImVec2 p1 = _Path.back();
01324     if (num_segments == 0)
01325     {
01326         IM_ASSERT(_Data->CurveTessellationTol > 0.0f);
01327         PathBezierCubicCurveToCasteljau(&_Path, p1.x, p1.y, p2.x, p2.y, p3.x, p3.y, p4.x, p4.y, _Data->CurveTessellationTol, 0); // Auto-tessellated
01328     }
01329     else
01330     {
01331         float t_step = 1.0f / (float)num_segments;
01332         for (int i_step = 1; i_step <= num_segments; i_step++)
01333             _Path.push_back(ImBezierCubicCalc(p1, p2, p3, p4, t_step * i_step));
01334     }
01335 }
01336 
01337 void ImDrawList::PathBezierQuadraticCurveTo(const ImVec2& p2, const ImVec2& p3, int num_segments)
01338 {
01339     ImVec2 p1 = _Path.back();
01340     if (num_segments == 0)
01341     {
01342         IM_ASSERT(_Data->CurveTessellationTol > 0.0f);
01343         PathBezierQuadraticCurveToCasteljau(&_Path, p1.x, p1.y, p2.x, p2.y, p3.x, p3.y, _Data->CurveTessellationTol, 0);// Auto-tessellated
01344     }
01345     else
01346     {
01347         float t_step = 1.0f / (float)num_segments;
01348         for (int i_step = 1; i_step <= num_segments; i_step++)
01349             _Path.push_back(ImBezierQuadraticCalc(p1, p2, p3, t_step * i_step));
01350     }
01351 }
