01353 static inline ImDrawFlags FixRectCornerFlags(ImDrawFlags flags)
01354 {
01355     /*
01356     IM_STATIC_ASSERT(ImDrawFlags_RoundCornersTopLeft == (1 << 4));
01357 #ifndef IMGUI_DISABLE_OBSOLETE_FUNCTIONS
01358     // Obsoleted in 1.82 (from February 2021). This code was stripped/simplified and mostly commented in 1.90 (from September 2023)
01359     // - Legacy Support for hard coded ~0 (used to be a suggested equivalent to ImDrawCornerFlags_All)
01360     if (flags == ~0)                    { return ImDrawFlags_RoundCornersAll; }
01361     // - Legacy Support for hard coded 0x01 to 0x0F (matching 15 out of 16 old flags combinations). Read details in older version of this code.
01362     if (flags >= 0x01 && flags <= 0x0F) { return (flags << 4); }
01363     // We cannot support hard coded 0x00 with 'float rounding > 0.0f' --> replace with ImDrawFlags_RoundCornersNone or use 'float rounding = 0.0f'
01364 #endif
01365     */
01366     // If this assert triggers, please update your code replacing hardcoded values with new ImDrawFlags_RoundCorners* values.
01367     // Note that ImDrawFlags_Closed (== 0x01) is an invalid flag for AddRect(), AddRectFilled(), PathRect() etc. anyway.
01368     // See details in 1.82 Changelog as well as 2021/03/12 and 2023/09/08 entries in "API BREAKING CHANGES" section.
01369     IM_ASSERT((flags & 0x0F) == 0 && "Misuse of legacy hardcoded ImDrawCornerFlags values!");
01370 
01371     if ((flags & ImDrawFlags_RoundCornersMask_) == 0)
01372         flags |= ImDrawFlags_RoundCornersAll;
01373 
01374     return flags;
01375 }
01376 
01377 void ImDrawList::PathRect(const ImVec2& a, const ImVec2& b, float rounding, ImDrawFlags flags)
01378 {
01379     if (rounding >= 0.5f)
01380     {
01381         flags = FixRectCornerFlags(flags);
01382         rounding = ImMin(rounding, ImFabs(b.x - a.x) * (((flags & ImDrawFlags_RoundCornersTop) == ImDrawFlags_RoundCornersTop) || ((flags & ImDrawFlags_RoundCornersBottom) == ImDrawFlags_RoundCornersBottom) ? 0.5f : 1.0f) - 1.0f);
01383         rounding = ImMin(rounding, ImFabs(b.y - a.y) * (((flags & ImDrawFlags_RoundCornersLeft) == ImDrawFlags_RoundCornersLeft) || ((flags & ImDrawFlags_RoundCornersRight) == ImDrawFlags_RoundCornersRight) ? 0.5f : 1.0f) - 1.0f);
01384     }
01385     if (rounding < 0.5f || (flags & ImDrawFlags_RoundCornersMask_) == ImDrawFlags_RoundCornersNone)
01386     {
01387         PathLineTo(a);
01388         PathLineTo(ImVec2(b.x, a.y));
01389         PathLineTo(b);
01390         PathLineTo(ImVec2(a.x, b.y));
01391     }
01392     else
01393     {
01394         const float rounding_tl = (flags & ImDrawFlags_RoundCornersTopLeft)     ? rounding : 0.0f;
01395         const float rounding_tr = (flags & ImDrawFlags_RoundCornersTopRight)    ? rounding : 0.0f;
01396         const float rounding_br = (flags & ImDrawFlags_RoundCornersBottomRight) ? rounding : 0.0f;
01397         const float rounding_bl = (flags & ImDrawFlags_RoundCornersBottomLeft)  ? rounding : 0.0f;
01398         PathArcToFast(ImVec2(a.x + rounding_tl, a.y + rounding_tl), rounding_tl, 6, 9);
01399         PathArcToFast(ImVec2(b.x - rounding_tr, a.y + rounding_tr), rounding_tr, 9, 12);
01400         PathArcToFast(ImVec2(b.x - rounding_br, b.y - rounding_br), rounding_br, 0, 3);
01401         PathArcToFast(ImVec2(a.x + rounding_bl, b.y - rounding_bl), rounding_bl, 3, 6);
01402     }
01403 }
