01414 // p_min = upper-left, p_max = lower-right
01415 // Note we don't render 1 pixels sized rectangles properly.
01416 void ImDrawList::AddRect(const ImVec2& p_min, const ImVec2& p_max, ImU32 col, float rounding, ImDrawFlags flags, float thickness)
01417 {
01418     if ((col & IM_COL32_A_MASK) == 0)
