01444 void ImDrawList::AddRectFilledMultiColor(const ImVec2& p_min, const ImVec2& p_max, ImU32 col_upr_left, ImU32 col_upr_right, ImU32 col_bot_right, ImU32 col_bot_left)
01445 {
01446     if (((col_upr_left | col_upr_right | col_bot_right | col_bot_left) & IM_COL32_A_MASK) == 0)
01447         return;
01448 
01449     const ImVec2 uv = _Data->TexUvWhitePixel;
01450     PrimReserve(6, 4);
01451     PrimWriteIdx((ImDrawIdx)(_VtxCurrentIdx)); PrimWriteIdx((ImDrawIdx)(_VtxCurrentIdx + 1)); PrimWriteIdx((ImDrawIdx)(_VtxCurrentIdx + 2));
01452     PrimWriteIdx((ImDrawIdx)(_VtxCurrentIdx)); PrimWriteIdx((ImDrawIdx)(_VtxCurrentIdx + 2)); PrimWriteIdx((ImDrawIdx)(_VtxCurrentIdx + 3));
01453     PrimWriteVtx(p_min, uv, col_upr_left);
01454     PrimWriteVtx(ImVec2(p_max.x, p_min.y), uv, col_upr_right);
01455     PrimWriteVtx(p_max, uv, col_bot_right);
01456     PrimWriteVtx(ImVec2(p_min.x, p_max.y), uv, col_bot_left);
