01505 void ImDrawList::AddCircle(const ImVec2& center, float radius, ImU32 col, int num_segments, float thickness)
01506 {
01507     if ((col & IM_COL32_A_MASK) == 0 || radius < 0.5f)
01508         return;
01509 
01510     if (num_segments <= 0)
01511     {
01512         // Use arc with automatic segment count
01513         _PathArcToFastEx(center, radius - 0.5f, 0, IM_DRAWLIST_ARCFAST_SAMPLE_MAX, 0);
01514         _Path.Size--;
01515     }
01516     else
01517     {
01518         // Explicit segment count (still clamp to avoid drawing insanely tessellated shapes)
01519         num_segments = ImClamp(num_segments, 3, IM_DRAWLIST_CIRCLE_AUTO_SEGMENT_MAX);
01520 
01521         // Because we are filling a closed shape we remove 1 from the count of segments/points
01522         const float a_max = (IM_PI * 2.0f) * ((float)num_segments - 1.0f) / (float)num_segments;
01523         PathArcTo(center, radius - 0.5f, 0.0f, a_max, num_segments - 1);
01524     }
01525 
01526     PathStroke(col, ImDrawFlags_Closed, thickness);
01527 }
