01537         _PathArcToFastEx(center, radius, 0, IM_DRAWLIST_ARCFAST_SAMPLE_MAX, 0);
01538         _Path.Size--;
01539     }
01540     else
01541     {
01542         // Explicit segment count (still clamp to avoid drawing insanely tessellated shapes)
01543         num_segments = ImClamp(num_segments, 3, IM_DRAWLIST_CIRCLE_AUTO_SEGMENT_MAX);
01544 
01545         // Because we are filling a closed shape we remove 1 from the count of segments/points
01546         const float a_max = (IM_PI * 2.0f) * ((float)num_segments - 1.0f) / (float)num_segments;
01547         PathArcTo(center, radius, 0.0f, a_max, num_segments - 1);
