01577 // Ellipse
01578 void ImDrawList::AddEllipse(const ImVec2& center, const ImVec2& radius, ImU32 col, float rot, int num_segments, float thickness)
01579 {
01580     if ((col & IM_COL32_A_MASK) == 0)
01581         return;
01582 
01583     if (num_segments <= 0)
01584         num_segments = _CalcCircleAutoSegmentCount(ImMax(radius.x, radius.y)); // A bit pessimistic, maybe there's a better computation to do here.
01585 
01586     // Because we are filling a closed shape we remove 1 from the count of segments/points
01587     const float a_max = IM_PI * 2.0f * ((float)num_segments - 1.0f) / (float)num_segments;
