01628 void ImDrawList::AddText(const ImFont* font, float font_size, const ImVec2& pos, ImU32 col, const char* text_begin, const char* text_end, float wrap_width, const ImVec4* cpu_fine_clip_rect)
01629 {
01630     if ((col & IM_COL32_A_MASK) == 0)
01631         return;
01632 
01633     // Accept null ranges
01634     if (text_begin == text_end || text_begin[0] == 0)
01635         return;
01636     if (text_end == NULL)
01637         text_end = text_begin + strlen(text_begin);
01638 
01639     // Pull default font/size from the shared ImDrawListSharedData instance
01640     if (font == NULL)
01641         font = _Data->Font;
01642     if (font_size == 0.0f)
01643         font_size = _Data->FontSize;
01644 
01645     IM_ASSERT(font->ContainerAtlas->TexID == _CmdHeader.TextureId);  // Use high-level ImGui::PushFont() or low-level ImDrawList::PushTextureId() to change font.
01646 
01647     ImVec4 clip_rect = _CmdHeader.ClipRect;
01648     if (cpu_fine_clip_rect)
01649     {
01650         clip_rect.x = ImMax(clip_rect.x, cpu_fine_clip_rect->x);
01651         clip_rect.y = ImMax(clip_rect.y, cpu_fine_clip_rect->y);
01652         clip_rect.z = ImMin(clip_rect.z, cpu_fine_clip_rect->z);
01653         clip_rect.w = ImMin(clip_rect.w, cpu_fine_clip_rect->w);
01654     }
01655     font->RenderText(this, font_size, pos, col, clip_rect, text_begin, text_end, wrap_width, cpu_fine_clip_rect != NULL);
01656 }
