01695 void ImDrawList::AddImageRounded(ImTextureID user_texture_id, const ImVec2& p_min, const ImVec2& p_max, const ImVec2& uv_min, const ImVec2& uv_max, ImU32 col, float rounding, ImDrawFlags flags)
01696 {
01697     if ((col & IM_COL32_A_MASK) == 0)
01698         return;
01699 
01700     flags = FixRectCornerFlags(flags);
01701     if (rounding < 0.5f || (flags & ImDrawFlags_RoundCornersMask_) == ImDrawFlags_RoundCornersNone)
01702     {
01703         AddImage(user_texture_id, p_min, p_max, uv_min, uv_max, col);
01704         return;
01705     }
01706 
01707     const bool push_texture_id = user_texture_id != _CmdHeader.TextureId;
01708     if (push_texture_id)
01709         PushTextureID(user_texture_id);
01710 
01711     int vert_start_idx = VtxBuffer.Size;
01712     PathRect(p_min, p_max, rounding, flags);
01713     PathFillConvex(col);
01714     int vert_end_idx = VtxBuffer.Size;
01715     ImGui::ShadeVertsLinearUV(this, vert_start_idx, vert_end_idx, p_min, p_max, uv_min, uv_max, true);
01716 
01717     if (push_texture_id)
01718         PopTextureID();
01719 }
01720 
01721 //-----------------------------------------------------------------------------
01722 // [SECTION] ImTriangulator, ImDrawList concave polygon fill
01723 //-----------------------------------------------------------------------------
01724 // Triangulate concave polygons. Based on "Triangulation by Ear Clipping" paper, O(N^2) complexity.
01725 // Reference: https://www.geometrictools.com/Documentation/TriangulationByEarClipping.pdf
01726 // Provided as a convenience for user but not used by main library.
01727 //-----------------------------------------------------------------------------
01728 // - ImTriangulator [Internal]
01729 // - AddConcavePolyFilled()
01730 //-----------------------------------------------------------------------------
01731 
01732 enum ImTriangulatorNodeType
01733 {
01734     ImTriangulatorNodeType_Convex,
01735     ImTriangulatorNodeType_Ear,
01736     ImTriangulatorNodeType_Reflex
01737 };
01738 
01739 struct ImTriangulatorNode
01740 {
01741     ImTriangulatorNodeType  Type;
01742     int                     Index;
01743     ImVec2                  Pos;
01744     ImTriangulatorNode*     Next;
01745     ImTriangulatorNode*     Prev;
01746 
01747     void    Unlink()        { Next->Prev = Prev; Prev->Next = Next; }
01748 };
01749 
01750 struct ImTriangulatorNodeSpan
01751 {
01752     ImTriangulatorNode**    Data = NULL;
01753     int                     Size = 0;
01754 
01755     void    push_back(ImTriangulatorNode* node) { Data[Size++] = node; }
01756     void    find_erase_unsorted(int idx)        { for (int i = Size - 1; i >= 0; i--) if (Data[i]->Index == idx) { Data[i] = Data[Size - 1]; Size--; return; } }
01757 };
01758 
01759 struct ImTriangulator
01760 {
01761     static int EstimateTriangleCount(int points_count)      { return (points_count < 3) ? 0 : points_count - 2; }
01762     static int EstimateScratchBufferSize(int points_count)  { return sizeof(ImTriangulatorNode) * points_count + sizeof(ImTriangulatorNode*) * points_count * 2; }
01763 
01764     void    Init(const ImVec2* points, int points_count, void* scratch_buffer);
01765     void    GetNextTriangle(unsigned int out_triangle[3]);     // Return relative indexes for next triangle
01766 
01767     // Internal functions
01768     void    BuildNodes(const ImVec2* points, int points_count);
01769     void    BuildReflexes();
01770     void    BuildEars();
01771     void    FlipNodeList();
01772     bool    IsEar(int i0, int i1, int i2, const ImVec2& v0, const ImVec2& v1, const ImVec2& v2) const;
01773     void    ReclassifyNode(ImTriangulatorNode* node);
01774 
01775     // Internal members
01776     int                     _TrianglesLeft = 0;
01777     ImTriangulatorNode*     _Nodes = NULL;
01778     ImTriangulatorNodeSpan  _Ears;
01779     ImTriangulatorNodeSpan  _Reflexes;
01780 };
01781 
01782 // Distribute storage for nodes, ears and reflexes.
01783 // FIXME-OPT: if everything is convex, we could report it to caller and let it switch to an convex renderer
01784 // (this would require first building reflexes to bail to convex if empty, without even building nodes)
01785 void ImTriangulator::Init(const ImVec2* points, int points_count, void* scratch_buffer)
01786 {
01787     IM_ASSERT(scratch_buffer != NULL && points_count >= 3);
01788     _TrianglesLeft = EstimateTriangleCount(points_count);
01789     _Nodes         = (ImTriangulatorNode*)scratch_buffer;                          // points_count x Node
01790     _Ears.Data     = (ImTriangulatorNode**)(_Nodes + points_count);                // points_count x Node*
01791     _Reflexes.Data = (ImTriangulatorNode**)(_Nodes + points_count) + points_count; // points_count x Node*
01792     BuildNodes(points, points_count);
01793     BuildReflexes();
01794     BuildEars();
01795 }
01796 
01797 void ImTriangulator::BuildNodes(const ImVec2* points, int points_count)
01798 {
01799     for (int i = 0; i < points_count; i++)
01800     {
01801         _Nodes[i].Type = ImTriangulatorNodeType_Convex;
01802         _Nodes[i].Index = i;
01803         _Nodes[i].Pos = points[i];
01804         _Nodes[i].Next = _Nodes + i + 1;
01805         _Nodes[i].Prev = _Nodes + i - 1;
01806     }
01807     _Nodes[0].Prev = _Nodes + points_count - 1;
01808     _Nodes[points_count - 1].Next = _Nodes;
01809 }
01810 
01811 void ImTriangulator::BuildReflexes()
01812 {
01813     ImTriangulatorNode* n1 = _Nodes;
01814     for (int i = _TrianglesLeft; i >= 0; i--, n1 = n1->Next)
01815     {
01816         if (ImTriangleIsClockwise(n1->Prev->Pos, n1->Pos, n1->Next->Pos))
01817             continue;
01818         n1->Type = ImTriangulatorNodeType_Reflex;
01819         _Reflexes.push_back(n1);
01820     }
01821 }
01822 
01823 void ImTriangulator::BuildEars()
01824 {
01825     ImTriangulatorNode* n1 = _Nodes;
01826     for (int i = _TrianglesLeft; i >= 0; i--, n1 = n1->Next)
01827     {
01828         if (n1->Type != ImTriangulatorNodeType_Convex)
01829             continue;
01830         if (!IsEar(n1->Prev->Index, n1->Index, n1->Next->Index, n1->Prev->Pos, n1->Pos, n1->Next->Pos))
01831             continue;
01832         n1->Type = ImTriangulatorNodeType_Ear;
01833         _Ears.push_back(n1);
01834     }
01835 }
01836 
01837 void ImTriangulator::GetNextTriangle(unsigned int out_triangle[3])
01838 {
01839     if (_Ears.Size == 0)
01840     {
01841         FlipNodeList();
01842 
01843         ImTriangulatorNode* node = _Nodes;
01844         for (int i = _TrianglesLeft; i >= 0; i--, node = node->Next)
01845             node->Type = ImTriangulatorNodeType_Convex;
01846         _Reflexes.Size = 0;
01847         BuildReflexes();
01848         BuildEars();
01849 
01850         // If we still don't have ears, it means geometry is degenerated.
01851         if (_Ears.Size == 0)
01852         {
01853             // Return first triangle available, mimicking the behavior of convex fill.
01854             IM_ASSERT(_TrianglesLeft > 0); // Geometry is degenerated
01855             _Ears.Data[0] = _Nodes;
01856             _Ears.Size    = 1;
01857         }
01858     }
01859 
01860     ImTriangulatorNode* ear = _Ears.Data[--_Ears.Size];
01861     out_triangle[0] = ear->Prev->Index;
01862     out_triangle[1] = ear->Index;
01863     out_triangle[2] = ear->Next->Index;
01864 
01865     ear->Unlink();
01866     if (ear == _Nodes)
01867         _Nodes = ear->Next;
01868 
01869     ReclassifyNode(ear->Prev);
01870     ReclassifyNode(ear->Next);
01871     _TrianglesLeft--;
01872 }
01873 
01874 void ImTriangulator::FlipNodeList()
01875 {
01876     ImTriangulatorNode* prev = _Nodes;
01877     ImTriangulatorNode* temp = _Nodes;
01878     ImTriangulatorNode* current = _Nodes->Next;
01879     prev->Next = prev;
01880     prev->Prev = prev;
01881     while (current != _Nodes)
01882     {
01883         temp = current->Next;
01884 
01885         current->Next = prev;
01886         prev->Prev = current;
01887         _Nodes->Next = current;
01888         current->Prev = _Nodes;
01889 
01890         prev = current;
01891         current = temp;
01892     }
01893     _Nodes = prev;
01894 }
01895 
01896 // A triangle is an ear is no other vertex is inside it. We can test reflexes vertices only (see reference algorithm)
01897 bool ImTriangulator::IsEar(int i0, int i1, int i2, const ImVec2& v0, const ImVec2& v1, const ImVec2& v2) const
01898 {
01899     ImTriangulatorNode** p_end = _Reflexes.Data + _Reflexes.Size;
01900     for (ImTriangulatorNode** p = _Reflexes.Data; p < p_end; p++)
01901     {
01902         ImTriangulatorNode* reflex = *p;
01903         if (reflex->Index != i0 && reflex->Index != i1 && reflex->Index != i2)
01904             if (ImTriangleContainsPoint(v0, v1, v2, reflex->Pos))
01905                 return false;
01906     }
01907     return true;
01908 }
01909 
01910 void ImTriangulator::ReclassifyNode(ImTriangulatorNode* n1)
01911 {
01912     // Classify node
01913     ImTriangulatorNodeType type;
01914     const ImTriangulatorNode* n0 = n1->Prev;
01915     const ImTriangulatorNode* n2 = n1->Next;
01916     if (!ImTriangleIsClockwise(n0->Pos, n1->Pos, n2->Pos))
01917         type = ImTriangulatorNodeType_Reflex;
01918     else if (IsEar(n0->Index, n1->Index, n2->Index, n0->Pos, n1->Pos, n2->Pos))
01919         type = ImTriangulatorNodeType_Ear;
01920     else
01921         type = ImTriangulatorNodeType_Convex;
01922 
01923     // Update lists when a type changes
01924     if (type == n1->Type)
01925         return;
01926     if (n1->Type == ImTriangulatorNodeType_Reflex)
01927         _Reflexes.find_erase_unsorted(n1->Index);
01928     else if (n1->Type == ImTriangulatorNodeType_Ear)
01929         _Ears.find_erase_unsorted(n1->Index);
01930     if (type == ImTriangulatorNodeType_Reflex)
01931         _Reflexes.push_back(n1);
01932     else if (type == ImTriangulatorNodeType_Ear)
01933         _Ears.push_back(n1);
01934     n1->Type = type;
01935 }
01936 
01937 // Use ear-clipping algorithm to triangulate a simple polygon (no self-interaction, no holes).
01938 // (Reminder: we don't perform any coarse clipping/culling in ImDrawList layer!
01939 // It is up to caller to ensure not making costly calls that will be outside of visible area.
01940 // As concave fill is noticeably more expensive than other primitives, be mindful of this...
01941 // Caller can build AABB of points, and avoid filling if 'draw_list->_CmdHeader.ClipRect.Overlays(points_bb) == false')
01942 void ImDrawList::AddConcavePolyFilled(const ImVec2* points, const int points_count, ImU32 col)
01943 {
01944     if (points_count < 3 || (col & IM_COL32_A_MASK) == 0)
01945         return;
01946 
01947     const ImVec2 uv = _Data->TexUvWhitePixel;
01948     ImTriangulator triangulator;
01949     unsigned int triangle[3];
01950     if (Flags & ImDrawListFlags_AntiAliasedFill)
01951     {
01952         // Anti-aliased Fill
01953         const float AA_SIZE = _FringeScale;
01954         const ImU32 col_trans = col & ~IM_COL32_A_MASK;
01955         const int idx_count = (points_count - 2) * 3 + points_count * 6;
01956         const int vtx_count = (points_count * 2);
01957         PrimReserve(idx_count, vtx_count);
01958 
01959         // Add indexes for fill
01960         unsigned int vtx_inner_idx = _VtxCurrentIdx;
01961         unsigned int vtx_outer_idx = _VtxCurrentIdx + 1;
01962 
01963         _Data->TempBuffer.reserve_discard((ImTriangulator::EstimateScratchBufferSize(points_count) + sizeof(ImVec2)) / sizeof(ImVec2));
01964         triangulator.Init(points, points_count, _Data->TempBuffer.Data);
01965         while (triangulator._TrianglesLeft > 0)
01966         {
01967             triangulator.GetNextTriangle(triangle);
01968             _IdxWritePtr[0] = (ImDrawIdx)(vtx_inner_idx + (triangle[0] << 1)); _IdxWritePtr[1] = (ImDrawIdx)(vtx_inner_idx + (triangle[1] << 1)); _IdxWritePtr[2] = (ImDrawIdx)(vtx_inner_idx + (triangle[2] << 1));
01969             _IdxWritePtr += 3;
01970         }
01971 
01972         // Compute normals
01973         _Data->TempBuffer.reserve_discard(points_count);
01974         ImVec2* temp_normals = _Data->TempBuffer.Data;
01975         for (int i0 = points_count - 1, i1 = 0; i1 < points_count; i0 = i1++)
01976         {
01977             const ImVec2& p0 = points[i0];
01978             const ImVec2& p1 = points[i1];
01979             float dx = p1.x - p0.x;
01980             float dy = p1.y - p0.y;
01981             IM_NORMALIZE2F_OVER_ZERO(dx, dy);
01982             temp_normals[i0].x = dy;
01983             temp_normals[i0].y = -dx;
01984         }
01985 
01986         for (int i0 = points_count - 1, i1 = 0; i1 < points_count; i0 = i1++)
01987         {
01988             // Average normals
01989             const ImVec2& n0 = temp_normals[i0];
01990             const ImVec2& n1 = temp_normals[i1];
01991             float dm_x = (n0.x + n1.x) * 0.5f;
01992             float dm_y = (n0.y + n1.y) * 0.5f;
01993             IM_FIXNORMAL2F(dm_x, dm_y);
01994             dm_x *= AA_SIZE * 0.5f;
01995             dm_y *= AA_SIZE * 0.5f;
01996 
01997             // Add vertices
01998             _VtxWritePtr[0].pos.x = (points[i1].x - dm_x); _VtxWritePtr[0].pos.y = (points[i1].y - dm_y); _VtxWritePtr[0].uv = uv; _VtxWritePtr[0].col = col;        // Inner
01999             _VtxWritePtr[1].pos.x = (points[i1].x + dm_x); _VtxWritePtr[1].pos.y = (points[i1].y + dm_y); _VtxWritePtr[1].uv = uv; _VtxWritePtr[1].col = col_trans;  // Outer
02000             _VtxWritePtr += 2;
02001 
02002             // Add indexes for fringes
02003             _IdxWritePtr[0] = (ImDrawIdx)(vtx_inner_idx + (i1 << 1)); _IdxWritePtr[1] = (ImDrawIdx)(vtx_inner_idx + (i0 << 1)); _IdxWritePtr[2] = (ImDrawIdx)(vtx_outer_idx + (i0 << 1));
02004             _IdxWritePtr[3] = (ImDrawIdx)(vtx_outer_idx + (i0 << 1)); _IdxWritePtr[4] = (ImDrawIdx)(vtx_outer_idx + (i1 << 1)); _IdxWritePtr[5] = (ImDrawIdx)(vtx_inner_idx + (i1 << 1));
02005             _IdxWritePtr += 6;
02006         }
02007         _VtxCurrentIdx += (ImDrawIdx)vtx_count;
02008     }
02009     else
02010     {
02011         // Non Anti-aliased Fill
02012         const int idx_count = (points_count - 2) * 3;
02013         const int vtx_count = points_count;
02014         PrimReserve(idx_count, vtx_count);
02015         for (int i = 0; i < vtx_count; i++)
02016         {
02017             _VtxWritePtr[0].pos = points[i]; _VtxWritePtr[0].uv = uv; _VtxWritePtr[0].col = col;
02018             _VtxWritePtr++;
02019         }
02020         _Data->TempBuffer.reserve_discard((ImTriangulator::EstimateScratchBufferSize(points_count) + sizeof(ImVec2)) / sizeof(ImVec2));
02021         triangulator.Init(points, points_count, _Data->TempBuffer.Data);
02022         while (triangulator._TrianglesLeft > 0)
02023         {
02024             triangulator.GetNextTriangle(triangle);
02025             _IdxWritePtr[0] = (ImDrawIdx)(_VtxCurrentIdx + triangle[0]); _IdxWritePtr[1] = (ImDrawIdx)(_VtxCurrentIdx + triangle[1]); _IdxWritePtr[2] = (ImDrawIdx)(_VtxCurrentIdx + triangle[2]);
02026             _IdxWritePtr += 3;
02027         }
02028         _VtxCurrentIdx += (ImDrawIdx)vtx_count;
02029     }
02030 }
02031 
02032 //-----------------------------------------------------------------------------
02033 // [SECTION] ImDrawListSplitter
02034 //-----------------------------------------------------------------------------
02035 // FIXME: This may be a little confusing, trying to be a little too low-level/optimal instead of just doing vector swap..
02036 //-----------------------------------------------------------------------------
02037 
02038 void ImDrawListSplitter::ClearFreeMemory()
02039 {
02040     for (int i = 0; i < _Channels.Size; i++)
02041     {
02042         if (i == _Current)
02043             memset(&_Channels[i], 0, sizeof(_Channels[i]));  // Current channel is a copy of CmdBuffer/IdxBuffer, don't destruct again
02044         _Channels[i]._CmdBuffer.clear();
02045         _Channels[i]._IdxBuffer.clear();
02046     }
02047     _Current = 0;
02048     _Count = 1;
02049     _Channels.clear();
02050 }
02051 
02052 void ImDrawListSplitter::Split(ImDrawList* draw_list, int channels_count)
02053 {
02054     IM_UNUSED(draw_list);
02055     IM_ASSERT(_Current == 0 && _Count <= 1 && "Nested channel splitting is not supported. Please use separate instances of ImDrawListSplitter.");
02056     int old_channels_count = _Channels.Size;
02057     if (old_channels_count < channels_count)
02058     {
02059         _Channels.reserve(channels_count); // Avoid over reserving since this is likely to stay stable
02060         _Channels.resize(channels_count);
02061     }
02062     _Count = channels_count;
02063 
02064     // Channels[] (24/32 bytes each) hold storage that we'll swap with draw_list->_CmdBuffer/_IdxBuffer
02065     // The content of Channels[0] at this point doesn't matter. We clear it to make state tidy in a debugger but we don't strictly need to.
02066     // When we switch to the next channel, we'll copy draw_list->_CmdBuffer/_IdxBuffer into Channels[0] and then Channels[1] into draw_list->CmdBuffer/_IdxBuffer
02067     memset(&_Channels[0], 0, sizeof(ImDrawChannel));
02068     for (int i = 1; i < channels_count; i++)
02069     {
02070         if (i >= old_channels_count)
02071         {
02072             IM_PLACEMENT_NEW(&_Channels[i]) ImDrawChannel();
02073         }
02074         else
02075         {
02076             _Channels[i]._CmdBuffer.resize(0);
02077             _Channels[i]._IdxBuffer.resize(0);
02078         }
02079     }
02080 }
02081 
02082 void ImDrawListSplitter::Merge(ImDrawList* draw_list)
02083 {
02084     // Note that we never use or rely on _Channels.Size because it is merely a buffer that we never shrink back to 0 to keep all sub-buffers ready for use.
02085     if (_Count <= 1)
02086         return;
02087 
02088     SetCurrentChannel(draw_list, 0);
02089     draw_list->_PopUnusedDrawCmd();
02090 
02091     // Calculate our final buffer sizes. Also fix the incorrect IdxOffset values in each command.
02092     int new_cmd_buffer_count = 0;
02093     int new_idx_buffer_count = 0;
02094     ImDrawCmd* last_cmd = (_Count > 0 && draw_list->CmdBuffer.Size > 0) ? &draw_list->CmdBuffer.back() : NULL;
02095     int idx_offset = last_cmd ? last_cmd->IdxOffset + last_cmd->ElemCount : 0;
02096     for (int i = 1; i < _Count; i++)
02097     {
02098         ImDrawChannel& ch = _Channels[i];
02099         if (ch._CmdBuffer.Size > 0 && ch._CmdBuffer.back().ElemCount == 0 && ch._CmdBuffer.back().UserCallback == NULL) // Equivalent of PopUnusedDrawCmd()
02100             ch._CmdBuffer.pop_back();
02101 
02102         if (ch._CmdBuffer.Size > 0 && last_cmd != NULL)
02103         {
02104             // Do not include ImDrawCmd_AreSequentialIdxOffset() in the compare as we rebuild IdxOffset values ourselves.
02105             // Manipulating IdxOffset (e.g. by reordering draw commands like done by RenderDimmedBackgroundBehindWindow()) is not supported within a splitter.
02106             ImDrawCmd* next_cmd = &ch._CmdBuffer[0];
02107             if (ImDrawCmd_HeaderCompare(last_cmd, next_cmd) == 0 && last_cmd->UserCallback == NULL && next_cmd->UserCallback == NULL)
02108             {
02109                 // Merge previous channel last draw command with current channel first draw command if matching.
02110                 last_cmd->ElemCount += next_cmd->ElemCount;
02111                 idx_offset += next_cmd->ElemCount;
02112                 ch._CmdBuffer.erase(ch._CmdBuffer.Data); // FIXME-OPT: Improve for multiple merges.
02113             }
02114         }
02115         if (ch._CmdBuffer.Size > 0)
02116             last_cmd = &ch._CmdBuffer.back();
02117         new_cmd_buffer_count += ch._CmdBuffer.Size;
02118         new_idx_buffer_count += ch._IdxBuffer.Size;
02119         for (int cmd_n = 0; cmd_n < ch._CmdBuffer.Size; cmd_n++)
02120         {
02121             ch._CmdBuffer.Data[cmd_n].IdxOffset = idx_offset;
02122             idx_offset += ch._CmdBuffer.Data[cmd_n].ElemCount;
02123         }
02124     }
02125     draw_list->CmdBuffer.resize(draw_list->CmdBuffer.Size + new_cmd_buffer_count);
02126     draw_list->IdxBuffer.resize(draw_list->IdxBuffer.Size + new_idx_buffer_count);
02127 
02128     // Write commands and indices in order (they are fairly small structures, we don't copy vertices only indices)
02129     ImDrawCmd* cmd_write = draw_list->CmdBuffer.Data + draw_list->CmdBuffer.Size - new_cmd_buffer_count;
02130     ImDrawIdx* idx_write = draw_list->IdxBuffer.Data + draw_list->IdxBuffer.Size - new_idx_buffer_count;
02131     for (int i = 1; i < _Count; i++)
02132     {
02133         ImDrawChannel& ch = _Channels[i];
02134         if (int sz = ch._CmdBuffer.Size) { memcpy(cmd_write, ch._CmdBuffer.Data, sz * sizeof(ImDrawCmd)); cmd_write += sz; }
02135         if (int sz = ch._IdxBuffer.Size) { memcpy(idx_write, ch._IdxBuffer.Data, sz * sizeof(ImDrawIdx)); idx_write += sz; }
02136     }
02137     draw_list->_IdxWritePtr = idx_write;
02138 
02139     // Ensure there's always a non-callback draw command trailing the command-buffer
02140     if (draw_list->CmdBuffer.Size == 0 || draw_list->CmdBuffer.back().UserCallback != NULL)
02141         draw_list->AddDrawCmd();
02142 
02143     // If current command is used with different settings we need to add a new command
02144     ImDrawCmd* curr_cmd = &draw_list->CmdBuffer.Data[draw_list->CmdBuffer.Size - 1];
02145     if (curr_cmd->ElemCount == 0)
02146         ImDrawCmd_HeaderCopy(curr_cmd, &draw_list->_CmdHeader); // Copy ClipRect, TextureId, VtxOffset
02147     else if (ImDrawCmd_HeaderCompare(curr_cmd, &draw_list->_CmdHeader) != 0)
02148         draw_list->AddDrawCmd();
02149 
02150     _Count = 1;
02151 }
02152 
02153 void ImDrawListSplitter::SetCurrentChannel(ImDrawList* draw_list, int idx)
02154 {
02155     IM_ASSERT(idx >= 0 && idx < _Count);
02156     if (_Current == idx)
02157         return;
02158 
02159     // Overwrite ImVector (12/16 bytes), four times. This is merely a silly optimization instead of doing .swap()
02160     memcpy(&_Channels.Data[_Current]._CmdBuffer, &draw_list->CmdBuffer, sizeof(draw_list->CmdBuffer));
02161     memcpy(&_Channels.Data[_Current]._IdxBuffer, &draw_list->IdxBuffer, sizeof(draw_list->IdxBuffer));
02162     _Current = idx;
02163     memcpy(&draw_list->CmdBuffer, &_Channels.Data[idx]._CmdBuffer, sizeof(draw_list->CmdBuffer));
02164     memcpy(&draw_list->IdxBuffer, &_Channels.Data[idx]._IdxBuffer, sizeof(draw_list->IdxBuffer));
02165     draw_list->_IdxWritePtr = draw_list->IdxBuffer.Data + draw_list->IdxBuffer.Size;
02166 
02167     // If current command is used with different settings we need to add a new command
02168     ImDrawCmd* curr_cmd = (draw_list->CmdBuffer.Size == 0) ? NULL : &draw_list->CmdBuffer.Data[draw_list->CmdBuffer.Size - 1];
02169     if (curr_cmd == NULL)
02170         draw_list->AddDrawCmd();
02171     else if (curr_cmd->ElemCount == 0)
02172         ImDrawCmd_HeaderCopy(curr_cmd, &draw_list->_CmdHeader); // Copy ClipRect, TextureId, VtxOffset
02173     else if (ImDrawCmd_HeaderCompare(curr_cmd, &draw_list->_CmdHeader) != 0)
02174         draw_list->AddDrawCmd();
02175 }
