02181 void ImDrawData::Clear()
02182 {
02183     Valid = false;
02184     CmdListsCount = TotalIdxCount = TotalVtxCount = 0;
02185     CmdLists.resize(0); // The ImDrawList are NOT owned by ImDrawData but e.g. by ImGuiContext, so we don't clear them.
02186     DisplayPos = DisplaySize = FramebufferScale = ImVec2(0.0f, 0.0f);
02187     OwnerViewport = NULL;
02188 }
02189 
02190 // Important: 'out_list' is generally going to be draw_data->CmdLists, but may be another temporary list
02191 // as long at it is expected that the result will be later merged into draw_data->CmdLists[].
02192 void ImGui::AddDrawListToDrawDataEx(ImDrawData* draw_data, ImVector<ImDrawList*>* out_list, ImDrawList* draw_list)
02193 {
02194     if (draw_list->CmdBuffer.Size == 0)
02195         return;
02196     if (draw_list->CmdBuffer.Size == 1 && draw_list->CmdBuffer[0].ElemCount == 0 && draw_list->CmdBuffer[0].UserCallback == NULL)
02197         return;
02198 
02199     // Draw list sanity check. Detect mismatch between PrimReserve() calls and incrementing _VtxCurrentIdx, _VtxWritePtr etc.
02200     // May trigger for you if you are using PrimXXX functions incorrectly.
02201     IM_ASSERT(draw_list->VtxBuffer.Size == 0 || draw_list->_VtxWritePtr == draw_list->VtxBuffer.Data + draw_list->VtxBuffer.Size);
02202     IM_ASSERT(draw_list->IdxBuffer.Size == 0 || draw_list->_IdxWritePtr == draw_list->IdxBuffer.Data + draw_list->IdxBuffer.Size);
02203     if (!(draw_list->Flags & ImDrawListFlags_AllowVtxOffset))
02204         IM_ASSERT((int)draw_list->_VtxCurrentIdx == draw_list->VtxBuffer.Size);
02205 
02206     // Check that draw_list doesn't use more vertices than indexable (default ImDrawIdx = unsigned short = 2 bytes = 64K vertices per ImDrawList = per window)
02207     // If this assert triggers because you are drawing lots of stuff manually:
02208     // - First, make sure you are coarse clipping yourself and not trying to draw many things outside visible bounds.
02209     //   Be mindful that the lower-level ImDrawList API doesn't filter vertices. Use the Metrics/Debugger window to inspect draw list contents.
02210     // - If you want large meshes with more than 64K vertices, you can either:
02211     //   (A) Handle the ImDrawCmd::VtxOffset value in your renderer backend, and set 'io.BackendFlags |= ImGuiBackendFlags_RendererHasVtxOffset'.
02212     //       Most example backends already support this from 1.71. Pre-1.71 backends won't.
02213     //       Some graphics API such as GL ES 1/2 don't have a way to offset the starting vertex so it is not supported for them.
02214     //   (B) Or handle 32-bit indices in your renderer backend, and uncomment '#define ImDrawIdx unsigned int' line in imconfig.h.
02215     //       Most example backends already support this. For example, the OpenGL example code detect index size at compile-time:
02216     //         glDrawElements(GL_TRIANGLES, (GLsizei)pcmd->ElemCount, sizeof(ImDrawIdx) == 2 ? GL_UNSIGNED_SHORT : GL_UNSIGNED_INT, idx_buffer_offset);
02217     //       Your own engine or render API may use different parameters or function calls to specify index sizes.
02218     //       2 and 4 bytes indices are generally supported by most graphics API.
02219     // - If for some reason neither of those solutions works for you, a workaround is to call BeginChild()/EndChild() before reaching
02220     //   the 64K limit to split your draw commands in multiple draw lists.
02221     if (sizeof(ImDrawIdx) == 2)
02222         IM_ASSERT(draw_list->_VtxCurrentIdx < (1 << 16) && "Too many vertices in ImDrawList using 16-bit indices. Read comment above");
02223 
02224     // Add to output list + records state in ImDrawData
02225     out_list->push_back(draw_list);
02226     draw_data->CmdListsCount++;
02227     draw_data->TotalVtxCount += draw_list->VtxBuffer.Size;
02228     draw_data->TotalIdxCount += draw_list->IdxBuffer.Size;
02229 }
02230 
02231 void ImDrawData::AddDrawList(ImDrawList* draw_list)
02232 {
02233     IM_ASSERT(CmdLists.Size == CmdListsCount);
02234     draw_list->_PopUnusedDrawCmd();
02235     ImGui::AddDrawListToDrawDataEx(this, &CmdLists, draw_list);
02236 }
02237 
02238 // For backward compatibility: convert all buffers from indexed to de-indexed, in case you cannot render indexed. Note: this is slow and most likely a waste of resources. Always prefer indexed rendering!
02239 void ImDrawData::DeIndexAllBuffers()
02240 {
02241     ImVector<ImDrawVert> new_vtx_buffer;
02242     TotalVtxCount = TotalIdxCount = 0;
02243     for (int i = 0; i < CmdListsCount; i++)
02244     {
02245         ImDrawList* cmd_list = CmdLists[i];
02246         if (cmd_list->IdxBuffer.empty())
02247             continue;
02248         new_vtx_buffer.resize(cmd_list->IdxBuffer.Size);
02249         for (int j = 0; j < cmd_list->IdxBuffer.Size; j++)
02250             new_vtx_buffer[j] = cmd_list->VtxBuffer[cmd_list->IdxBuffer[j]];
02251         cmd_list->VtxBuffer.swap(new_vtx_buffer);
02252         cmd_list->IdxBuffer.resize(0);
02253         TotalVtxCount += cmd_list->VtxBuffer.Size;
02254     }
02255 }
