02257 // Helper to scale the ClipRect field of each ImDrawCmd.
02258 // Use if your final output buffer is at a different scale than draw_data->DisplaySize,
02259 // or if there is a difference between your window resolution and framebuffer resolution.
02260 void ImDrawData::ScaleClipRects(const ImVec2& fb_scale)
02261 {
02262     for (ImDrawList* draw_list : CmdLists)
02263         for (ImDrawCmd& cmd : draw_list->CmdBuffer)
02264             cmd.ClipRect = ImVec4(cmd.ClipRect.x * fb_scale.x, cmd.ClipRect.y * fb_scale.y, cmd.ClipRect.z * fb_scale.x, cmd.ClipRect.w * fb_scale.y);
02265 }
