02269 //-----------------------------------------------------------------------------
02270 
02271 // Generic linear color gradient, write to RGB fields, leave A untouched.
02272 void ImGui::ShadeVertsLinearColorGradientKeepAlpha(ImDrawList* draw_list, int vert_start_idx, int vert_end_idx, ImVec2 gradient_p0, ImVec2 gradient_p1, ImU32 col0, ImU32 col1)
02273 {
02274     ImVec2 gradient_extent = gradient_p1 - gradient_p0;
02275     float gradient_inv_length2 = 1.0f / ImLengthSqr(gradient_extent);
02276     ImDrawVert* vert_start = draw_list->VtxBuffer.Data + vert_start_idx;
02277     ImDrawVert* vert_end = draw_list->VtxBuffer.Data + vert_end_idx;
02278     const int col0_r = (int)(col0 >> IM_COL32_R_SHIFT) & 0xFF;
02279     const int col0_g = (int)(col0 >> IM_COL32_G_SHIFT) & 0xFF;
02280     const int col0_b = (int)(col0 >> IM_COL32_B_SHIFT) & 0xFF;
02281     const int col_delta_r = ((int)(col1 >> IM_COL32_R_SHIFT) & 0xFF) - col0_r;
02282     const int col_delta_g = ((int)(col1 >> IM_COL32_G_SHIFT) & 0xFF) - col0_g;
02283     const int col_delta_b = ((int)(col1 >> IM_COL32_B_SHIFT) & 0xFF) - col0_b;
02284     for (ImDrawVert* vert = vert_start; vert < vert_end; vert++)
02285     {
02286         float d = ImDot(vert->pos - gradient_p0, gradient_extent);
02287         float t = ImClamp(d * gradient_inv_length2, 0.0f, 1.0f);
02288         int r = (int)(col0_r + col_delta_r * t);
02289         int g = (int)(col0_g + col_delta_g * t);
02290         int b = (int)(col0_b + col_delta_b * t);
02291         vert->col = (r << IM_COL32_R_SHIFT) | (g << IM_COL32_G_SHIFT) | (b << IM_COL32_B_SHIFT) | (vert->col & IM_COL32_A_MASK);
02292     }
02293 }
02294 
02295 // Distribute UV over (a, b) rectangle
02296 void ImGui::ShadeVertsLinearUV(ImDrawList* draw_list, int vert_start_idx, int vert_end_idx, const ImVec2& a, const ImVec2& b, const ImVec2& uv_a, const ImVec2& uv_b, bool clamp)
02297 {
02298     const ImVec2 size = b - a;
02299     const ImVec2 uv_size = uv_b - uv_a;
02300     const ImVec2 scale = ImVec2(
02301         size.x != 0.0f ? (uv_size.x / size.x) : 0.0f,
02302         size.y != 0.0f ? (uv_size.y / size.y) : 0.0f);
02303 
02304     ImDrawVert* vert_start = draw_list->VtxBuffer.Data + vert_start_idx;
02305     ImDrawVert* vert_end = draw_list->VtxBuffer.Data + vert_end_idx;
02306     if (clamp)
02307     {
02308         const ImVec2 min = ImMin(uv_a, uv_b);
02309         const ImVec2 max = ImMax(uv_a, uv_b);
02310         for (ImDrawVert* vertex = vert_start; vertex < vert_end; ++vertex)
02311             vertex->uv = ImClamp(uv_a + ImMul(ImVec2(vertex->pos.x, vertex->pos.y) - a, scale), min, max);
02312     }
02313     else
02314     {
02315         for (ImDrawVert* vertex = vert_start; vertex < vert_end; ++vertex)
02316             vertex->uv = uv_a + ImMul(ImVec2(vertex->pos.x, vertex->pos.y) - a, scale);
02317     }
02318 }
02319 
02320 void ImGui::ShadeVertsTransformPos(ImDrawList* draw_list, int vert_start_idx, int vert_end_idx, const ImVec2& pivot_in, float cos_a, float sin_a, const ImVec2& pivot_out)
02321 {
02322     ImDrawVert* vert_start = draw_list->VtxBuffer.Data + vert_start_idx;
02323     ImDrawVert* vert_end = draw_list->VtxBuffer.Data + vert_end_idx;
02324     for (ImDrawVert* vertex = vert_start; vertex < vert_end; ++vertex)
02325         vertex->pos = ImRotate(vertex->pos- pivot_in, cos_a, sin_a) + pivot_out;
02326 }
