02411 void    ImFontAtlas::ClearInputData()
02412 {
02413     IM_ASSERT(!Locked && "Cannot modify a locked ImFontAtlas between NewFrame() and EndFrame/Render()!");
02414     for (ImFontConfig& font_cfg : ConfigData)
02415         if (font_cfg.FontData && font_cfg.FontDataOwnedByAtlas)
02416         {
02417             IM_FREE(font_cfg.FontData);
02418             font_cfg.FontData = NULL;
02419         }
02420 
02421     // When clearing this we lose access to the font name and other information used to build the font.
02422     for (ImFont* font : Fonts)
02423         if (font->ConfigData >= ConfigData.Data && font->ConfigData < ConfigData.Data + ConfigData.Size)
02424         {
02425             font->ConfigData = NULL;
02426             font->ConfigDataCount = 0;
02427         }
02428     ConfigData.clear();
02429     CustomRects.clear();
02430     PackIdMouseCursors = PackIdLines = -1;
02431     // Important: we leave TexReady untouched
02432 }
02433 
02434 void    ImFontAtlas::ClearTexData()
02435 {
02436     IM_ASSERT(!Locked && "Cannot modify a locked ImFontAtlas between NewFrame() and EndFrame/Render()!");
02437     if (TexPixelsAlpha8)
02438         IM_FREE(TexPixelsAlpha8);
02439     if (TexPixelsRGBA32)
02440         IM_FREE(TexPixelsRGBA32);
02441     TexPixelsAlpha8 = NULL;
02442     TexPixelsRGBA32 = NULL;
02443     TexPixelsUseColors = false;
02444     // Important: we leave TexReady untouched
02445 }
02446 
02447 void    ImFontAtlas::ClearFonts()
02448 {
02449     IM_ASSERT(!Locked && "Cannot modify a locked ImFontAtlas between NewFrame() and EndFrame/Render()!");
02450     Fonts.clear_delete();
02451     TexReady = false;
02452 }
02453 
02454 void    ImFontAtlas::Clear()
02455 {
02456     ClearInputData();
02457     ClearTexData();
02458     ClearFonts();
02459 }
