02461 void    ImFontAtlas::GetTexDataAsAlpha8(unsigned char** out_pixels, int* out_width, int* out_height, int* out_bytes_per_pixel)
02462 {
02463     // Build atlas on demand
02464     if (TexPixelsAlpha8 == NULL)
02465         Build();
02466 
02467     *out_pixels = TexPixelsAlpha8;
02468     if (out_width) *out_width = TexWidth;
02469     if (out_height) *out_height = TexHeight;
02470     if (out_bytes_per_pixel) *out_bytes_per_pixel = 1;
02471 }
02472 
02473 void    ImFontAtlas::GetTexDataAsRGBA32(unsigned char** out_pixels, int* out_width, int* out_height, int* out_bytes_per_pixel)
02474 {
02475     // Convert to RGBA32 format on demand
02476     // Although it is likely to be the most commonly used format, our font rendering is 1 channel / 8 bpp
02477     if (!TexPixelsRGBA32)
02478     {
02479         unsigned char* pixels = NULL;
02480         GetTexDataAsAlpha8(&pixels, NULL, NULL);
02481         if (pixels)
02482         {
02483             TexPixelsRGBA32 = (unsigned int*)IM_ALLOC((size_t)TexWidth * (size_t)TexHeight * 4);
02484             const unsigned char* src = pixels;
02485             unsigned int* dst = TexPixelsRGBA32;
02486             for (int n = TexWidth * TexHeight; n > 0; n--)
02487                 *dst++ = IM_COL32(255, 255, 255, (unsigned int)(*src++));
02488         }
02489     }
02490 
02491     *out_pixels = (unsigned char*)TexPixelsRGBA32;
02492     if (out_width) *out_width = TexWidth;
02493     if (out_height) *out_height = TexHeight;
02494     if (out_bytes_per_pixel) *out_bytes_per_pixel = 4;
02495 }
