02497 ImFont* ImFontAtlas::AddFont(const ImFontConfig* font_cfg)
02498 {
02499     IM_ASSERT(!Locked && "Cannot modify a locked ImFontAtlas between NewFrame() and EndFrame/Render()!");
02500     IM_ASSERT(font_cfg->FontData != NULL && font_cfg->FontDataSize > 0);
02501     IM_ASSERT(font_cfg->SizePixels > 0.0f);
02502 
02503     // Create new font
02504     if (!font_cfg->MergeMode)
02505         Fonts.push_back(IM_NEW(ImFont));
02506     else
02507         IM_ASSERT(!Fonts.empty() && "Cannot use MergeMode for the first font"); // When using MergeMode make sure that a font has already been added before. You can use ImGui::GetIO().Fonts->AddFontDefault() to add the default imgui font.
02508 
02509     ConfigData.push_back(*font_cfg);
02510     ImFontConfig& new_font_cfg = ConfigData.back();
02511     if (new_font_cfg.DstFont == NULL)
02512         new_font_cfg.DstFont = Fonts.back();
02513     if (!new_font_cfg.FontDataOwnedByAtlas)
02514     {
02515         new_font_cfg.FontData = IM_ALLOC(new_font_cfg.FontDataSize);
02516         new_font_cfg.FontDataOwnedByAtlas = true;
02517         memcpy(new_font_cfg.FontData, font_cfg->FontData, (size_t)new_font_cfg.FontDataSize);
02518     }
02519 
02520     if (new_font_cfg.DstFont->EllipsisChar == (ImWchar)-1)
02521         new_font_cfg.DstFont->EllipsisChar = font_cfg->EllipsisChar;
02522 
02523     ImFontAtlasUpdateConfigDataPointers(this);
02524 
02525     // Invalidate texture
02526     TexReady = false;
02527     ClearTexData();
02528     return new_font_cfg.DstFont;
02529 }
02530 
02531 // Default font TTF is compressed with stb_compress then base85 encoded (see misc/fonts/binary_to_compressed_c.cpp for encoder)
02532 static unsigned int stb_decompress_length(const unsigned char* input);
02533 static unsigned int stb_decompress(unsigned char* output, const unsigned char* input, unsigned int length);
02534 static const char*  GetDefaultCompressedFontDataTTFBase85();
02535 static unsigned int Decode85Byte(char c)                                    { return c >= '\\' ? c-36 : c-35; }
02536 static void         Decode85(const unsigned char* src, unsigned char* dst)
02537 {
02538     while (*src)
02539     {
02540         unsigned int tmp = Decode85Byte(src[0]) + 85 * (Decode85Byte(src[1]) + 85 * (Decode85Byte(src[2]) + 85 * (Decode85Byte(src[3]) + 85 * Decode85Byte(src[4]))));
02541         dst[0] = ((tmp >> 0) & 0xFF); dst[1] = ((tmp >> 8) & 0xFF); dst[2] = ((tmp >> 16) & 0xFF); dst[3] = ((tmp >> 24) & 0xFF);   // We can't assume little-endianness.
02542         src += 5;
02543         dst += 4;
02544     }
02545 }
02546 
02547 // Load embedded ProggyClean.ttf at size 13, disable oversampling
02548 ImFont* ImFontAtlas::AddFontDefault(const ImFontConfig* font_cfg_template)
02549 {
02550     ImFontConfig font_cfg = font_cfg_template ? *font_cfg_template : ImFontConfig();
02551     if (!font_cfg_template)
02552     {
02553         font_cfg.OversampleH = font_cfg.OversampleV = 1;
02554         font_cfg.PixelSnapH = true;
02555     }
02556     if (font_cfg.SizePixels <= 0.0f)
02557         font_cfg.SizePixels = 13.0f * 1.0f;
02558     if (font_cfg.Name[0] == '\0')
02559         ImFormatString(font_cfg.Name, IM_ARRAYSIZE(font_cfg.Name), "ProggyClean.ttf, %dpx", (int)font_cfg.SizePixels);
02560     font_cfg.EllipsisChar = (ImWchar)0x0085;
02561     font_cfg.GlyphOffset.y = 1.0f * IM_TRUNC(font_cfg.SizePixels / 13.0f);  // Add +1 offset per 13 units
02562 
02563     const char* ttf_compressed_base85 = GetDefaultCompressedFontDataTTFBase85();
02564     const ImWchar* glyph_ranges = font_cfg.GlyphRanges != NULL ? font_cfg.GlyphRanges : GetGlyphRangesDefault();
02565     ImFont* font = AddFontFromMemoryCompressedBase85TTF(ttf_compressed_base85, font_cfg.SizePixels, &font_cfg, glyph_ranges);
02566     return font;
02567 }
