02569 ImFont* ImFontAtlas::AddFontFromFileTTF(const char* filename, float size_pixels, const ImFontConfig* font_cfg_template, const ImWchar* glyph_ranges)
02570 {
02571     IM_ASSERT(!Locked && "Cannot modify a locked ImFontAtlas between NewFrame() and EndFrame/Render()!");
02572     size_t data_size = 0;
02573     void* data = ImFileLoadToMemory(filename, "rb", &data_size, 0);
02574     if (!data)
02575     {
02576         IM_ASSERT_USER_ERROR(0, "Could not load font file!");
02577         return NULL;
02578     }
02579     ImFontConfig font_cfg = font_cfg_template ? *font_cfg_template : ImFontConfig();
02580     if (font_cfg.Name[0] == '\0')
02581     {
02582         // Store a short copy of filename into into the font name for convenience
02583         const char* p;
02584         for (p = filename + strlen(filename); p > filename && p[-1] != '/' && p[-1] != '\\'; p--) {}
02585         ImFormatString(font_cfg.Name, IM_ARRAYSIZE(font_cfg.Name), "%s, %.0fpx", p, size_pixels);
02586     }
02587     return AddFontFromMemoryTTF(data, (int)data_size, size_pixels, &font_cfg, glyph_ranges);
02588 }
02589 
02590 // NB: Transfer ownership of 'ttf_data' to ImFontAtlas, unless font_cfg_template->FontDataOwnedByAtlas == false. Owned TTF buffer will be deleted after Build().
02591 ImFont* ImFontAtlas::AddFontFromMemoryTTF(void* font_data, int font_data_size, float size_pixels, const ImFontConfig* font_cfg_template, const ImWchar* glyph_ranges)
02592 {
02593     IM_ASSERT(!Locked && "Cannot modify a locked ImFontAtlas between NewFrame() and EndFrame/Render()!");
02594     ImFontConfig font_cfg = font_cfg_template ? *font_cfg_template : ImFontConfig();
02595     IM_ASSERT(font_cfg.FontData == NULL);
02596     IM_ASSERT(font_data_size > 100 && "Incorrect value for font_data_size!"); // Heuristic to prevent accidentally passing a wrong value to font_data_size.
02597     font_cfg.FontData = font_data;
02598     font_cfg.FontDataSize = font_data_size;
02599     font_cfg.SizePixels = size_pixels > 0.0f ? size_pixels : font_cfg.SizePixels;
02600     if (glyph_ranges)
02601         font_cfg.GlyphRanges = glyph_ranges;
02602     return AddFont(&font_cfg);
02603 }
02604 
02605 ImFont* ImFontAtlas::AddFontFromMemoryCompressedTTF(const void* compressed_ttf_data, int compressed_ttf_size, float size_pixels, const ImFontConfig* font_cfg_template, const ImWchar* glyph_ranges)
02606 {
02607     const unsigned int buf_decompressed_size = stb_decompress_length((const unsigned char*)compressed_ttf_data);
02608     unsigned char* buf_decompressed_data = (unsigned char*)IM_ALLOC(buf_decompressed_size);
02609     stb_decompress(buf_decompressed_data, (const unsigned char*)compressed_ttf_data, (unsigned int)compressed_ttf_size);
02610 
02611     ImFontConfig font_cfg = font_cfg_template ? *font_cfg_template : ImFontConfig();
02612     IM_ASSERT(font_cfg.FontData == NULL);
02613     font_cfg.FontDataOwnedByAtlas = true;
02614     return AddFontFromMemoryTTF(buf_decompressed_data, (int)buf_decompressed_size, size_pixels, &font_cfg, glyph_ranges);
02615 }
02616 
02617 ImFont* ImFontAtlas::AddFontFromMemoryCompressedBase85TTF(const char* compressed_ttf_data_base85, float size_pixels, const ImFontConfig* font_cfg, const ImWchar* glyph_ranges)
02618 {
02619     int compressed_ttf_size = (((int)strlen(compressed_ttf_data_base85) + 4) / 5) * 4;
02620     void* compressed_ttf = IM_ALLOC((size_t)compressed_ttf_size);
02621     Decode85((const unsigned char*)compressed_ttf_data_base85, (unsigned char*)compressed_ttf);
02622     ImFont* font = AddFontFromMemoryCompressedTTF(compressed_ttf, compressed_ttf_size, size_pixels, font_cfg, glyph_ranges);
02623     IM_FREE(compressed_ttf);
02624     return font;
02625 }
