02665 bool ImFontAtlas::GetMouseCursorTexData(ImGuiMouseCursor cursor_type, ImVec2* out_offset, ImVec2* out_size, ImVec2 out_uv_border[2], ImVec2 out_uv_fill[2])
02666 {
02667     if (cursor_type <= ImGuiMouseCursor_None || cursor_type >= ImGuiMouseCursor_COUNT)
02668         return false;
02669     if (Flags & ImFontAtlasFlags_NoMouseCursors)
02670         return false;
02671 
02672     IM_ASSERT(PackIdMouseCursors != -1);
02673     ImFontAtlasCustomRect* r = GetCustomRectByIndex(PackIdMouseCursors);
02674     ImVec2 pos = FONT_ATLAS_DEFAULT_TEX_CURSOR_DATA[cursor_type][0] + ImVec2((float)r->X, (float)r->Y);
02675     ImVec2 size = FONT_ATLAS_DEFAULT_TEX_CURSOR_DATA[cursor_type][1];
02676     *out_size = size;
02677     *out_offset = FONT_ATLAS_DEFAULT_TEX_CURSOR_DATA[cursor_type][2];
02678     out_uv_border[0] = (pos) * TexUvScale;
02679     out_uv_border[1] = (pos + size) * TexUvScale;
02680     pos.x += FONT_ATLAS_DEFAULT_TEX_DATA_W + 1;
02681     out_uv_fill[0] = (pos) * TexUvScale;
02682     out_uv_fill[1] = (pos + size) * TexUvScale;
02683     return true;
02684 }
