02686 bool    ImFontAtlas::Build()
02687 {
02688     IM_ASSERT(!Locked && "Cannot modify a locked ImFontAtlas between NewFrame() and EndFrame/Render()!");
02689 
02690     // Default font is none are specified
02691     if (ConfigData.Size == 0)
02692         AddFontDefault();
02693 
02694     // Select builder
02695     // - Note that we do not reassign to atlas->FontBuilderIO, since it is likely to point to static data which
02696     //   may mess with some hot-reloading schemes. If you need to assign to this (for dynamic selection) AND are
02697     //   using a hot-reloading scheme that messes up static data, store your own instance of ImFontBuilderIO somewhere
02698     //   and point to it instead of pointing directly to return value of the GetBuilderXXX functions.
02699     const ImFontBuilderIO* builder_io = FontBuilderIO;
02700     if (builder_io == NULL)
02701     {
02702 #ifdef IMGUI_ENABLE_FREETYPE
02703         builder_io = ImGuiFreeType::GetBuilderForFreeType();
02704 #elif defined(IMGUI_ENABLE_STB_TRUETYPE)
02705         builder_io = ImFontAtlasGetBuilderForStbTruetype();
02706 #else
02707         IM_ASSERT(0); // Invalid Build function
02708 #endif
02709     }
02710 
02711     // Build
02712     return builder_io->FontBuilder_Build(this);
02713 }
02714 
02715 void    ImFontAtlasBuildMultiplyCalcLookupTable(unsigned char out_table[256], float in_brighten_factor)
02716 {
02717     for (unsigned int i = 0; i < 256; i++)
02718     {
02719         unsigned int value = (unsigned int)(i * in_brighten_factor);
02720         out_table[i] = value > 255 ? 255 : (value & 0xFF);
02721     }
02722 }
02723 
02724 void    ImFontAtlasBuildMultiplyRectAlpha8(const unsigned char table[256], unsigned char* pixels, int x, int y, int w, int h, int stride)
02725 {
02726     IM_ASSERT_PARANOID(w <= stride);
02727     unsigned char* data = pixels + x + y * stride;
02728     for (int j = h; j > 0; j--, data += stride - w)
02729         for (int i = w; i > 0; i--, data++)
02730             *data = table[*data];
02731 }
02732 
02733 #ifdef IMGUI_ENABLE_STB_TRUETYPE
02734 // Temporary data for one source font (multiple source fonts can be merged into one destination ImFont)
02735 // (C++03 doesn't allow instancing ImVector<> with function-local types so we declare the type here.)
02736 struct ImFontBuildSrcData
02737 {
02738     stbtt_fontinfo      FontInfo;
02739     stbtt_pack_range    PackRange;          // Hold the list of codepoints to pack (essentially points to Codepoints.Data)
02740     stbrp_rect*         Rects;              // Rectangle to pack. We first fill in their size and the packer will give us their position.
02741     stbtt_packedchar*   PackedChars;        // Output glyphs
02742     const ImWchar*      SrcRanges;          // Ranges as requested by user (user is allowed to request too much, e.g. 0x0020..0xFFFF)
02743     int                 DstIndex;           // Index into atlas->Fonts[] and dst_tmp_array[]
02744     int                 GlyphsHighest;      // Highest requested codepoint
02745     int                 GlyphsCount;        // Glyph count (excluding missing glyphs and glyphs already set by an earlier source font)
02746     ImBitVector         GlyphsSet;          // Glyph bit map (random access, 1-bit per codepoint. This will be a maximum of 8KB)
02747     ImVector<int>       GlyphsList;         // Glyph codepoints list (flattened version of GlyphsSet)
02748 };
02749 
02750 // Temporary data for one destination ImFont* (multiple source fonts can be merged into one destination ImFont)
02751 struct ImFontBuildDstData
02752 {
02753     int                 SrcCount;           // Number of source fonts targeting this destination font.
02754     int                 GlyphsHighest;
02755     int                 GlyphsCount;
02756     ImBitVector         GlyphsSet;          // This is used to resolve collision when multiple sources are merged into a same destination font.
02757 };
02758 
02759 static void UnpackBitVectorToFlatIndexList(const ImBitVector* in, ImVector<int>* out)
02760 {
02761     IM_ASSERT(sizeof(in->Storage.Data[0]) == sizeof(int));
02762     const ImU32* it_begin = in->Storage.begin();
02763     const ImU32* it_end = in->Storage.end();
02764     for (const ImU32* it = it_begin; it < it_end; it++)
02765         if (ImU32 entries_32 = *it)
02766             for (ImU32 bit_n = 0; bit_n < 32; bit_n++)
02767                 if (entries_32 & ((ImU32)1 << bit_n))
02768                     out->push_back((int)(((it - it_begin) << 5) + bit_n));
02769 }
02770 
02771 static bool ImFontAtlasBuildWithStbTruetype(ImFontAtlas* atlas)
02772 {
02773     IM_ASSERT(atlas->ConfigData.Size > 0);
02774 
02775     ImFontAtlasBuildInit(atlas);
02776 
02777     // Clear atlas
02778     atlas->TexID = (ImTextureID)NULL;
02779     atlas->TexWidth = atlas->TexHeight = 0;
02780     atlas->TexUvScale = ImVec2(0.0f, 0.0f);
02781     atlas->TexUvWhitePixel = ImVec2(0.0f, 0.0f);
02782     atlas->ClearTexData();
02783 
02784     // Temporary storage for building
02785     ImVector<ImFontBuildSrcData> src_tmp_array;
02786     ImVector<ImFontBuildDstData> dst_tmp_array;
02787     src_tmp_array.resize(atlas->ConfigData.Size);
02788     dst_tmp_array.resize(atlas->Fonts.Size);
02789     memset(src_tmp_array.Data, 0, (size_t)src_tmp_array.size_in_bytes());
02790     memset(dst_tmp_array.Data, 0, (size_t)dst_tmp_array.size_in_bytes());
02791 
02792     // 1. Initialize font loading structure, check font data validity
02793     for (int src_i = 0; src_i < atlas->ConfigData.Size; src_i++)
02794     {
02795         ImFontBuildSrcData& src_tmp = src_tmp_array[src_i];
02796         ImFontConfig& cfg = atlas->ConfigData[src_i];
02797         IM_ASSERT(cfg.DstFont && (!cfg.DstFont->IsLoaded() || cfg.DstFont->ContainerAtlas == atlas));
02798 
02799         // Find index from cfg.DstFont (we allow the user to set cfg.DstFont. Also it makes casual debugging nicer than when storing indices)
02800         src_tmp.DstIndex = -1;
02801         for (int output_i = 0; output_i < atlas->Fonts.Size && src_tmp.DstIndex == -1; output_i++)
02802             if (cfg.DstFont == atlas->Fonts[output_i])
02803                 src_tmp.DstIndex = output_i;
02804         if (src_tmp.DstIndex == -1)
02805         {
02806             IM_ASSERT(src_tmp.DstIndex != -1); // cfg.DstFont not pointing within atlas->Fonts[] array?
02807             return false;
02808         }
02809         // Initialize helper structure for font loading and verify that the TTF/OTF data is correct
02810         const int font_offset = stbtt_GetFontOffsetForIndex((unsigned char*)cfg.FontData, cfg.FontNo);
02811         IM_ASSERT(font_offset >= 0 && "FontData is incorrect, or FontNo cannot be found.");
02812         if (!stbtt_InitFont(&src_tmp.FontInfo, (unsigned char*)cfg.FontData, font_offset))
02813         {
02814             IM_ASSERT(0 && "stbtt_InitFont(): failed to parse FontData. It is correct and complete? Check FontDataSize.");
02815             return false;
02816         }
02817 
02818         // Measure highest codepoints
02819         ImFontBuildDstData& dst_tmp = dst_tmp_array[src_tmp.DstIndex];
02820         src_tmp.SrcRanges = cfg.GlyphRanges ? cfg.GlyphRanges : atlas->GetGlyphRangesDefault();
02821         for (const ImWchar* src_range = src_tmp.SrcRanges; src_range[0] && src_range[1]; src_range += 2)
02822         {
02823             // Check for valid range. This may also help detect *some* dangling pointers, because a common
02824             // user error is to setup ImFontConfig::GlyphRanges with a pointer to data that isn't persistent.
02825             IM_ASSERT(src_range[0] <= src_range[1]);
02826             src_tmp.GlyphsHighest = ImMax(src_tmp.GlyphsHighest, (int)src_range[1]);
02827         }
02828         dst_tmp.SrcCount++;
02829         dst_tmp.GlyphsHighest = ImMax(dst_tmp.GlyphsHighest, src_tmp.GlyphsHighest);
02830     }
02831 
02832     // 2. For every requested codepoint, check for their presence in the font data, and handle redundancy or overlaps between source fonts to avoid unused glyphs.
02833     int total_glyphs_count = 0;
02834     for (int src_i = 0; src_i < src_tmp_array.Size; src_i++)
02835     {
02836         ImFontBuildSrcData& src_tmp = src_tmp_array[src_i];
02837         ImFontBuildDstData& dst_tmp = dst_tmp_array[src_tmp.DstIndex];
02838         src_tmp.GlyphsSet.Create(src_tmp.GlyphsHighest + 1);
02839         if (dst_tmp.GlyphsSet.Storage.empty())
02840             dst_tmp.GlyphsSet.Create(dst_tmp.GlyphsHighest + 1);
02841 
02842         for (const ImWchar* src_range = src_tmp.SrcRanges; src_range[0] && src_range[1]; src_range += 2)
02843             for (unsigned int codepoint = src_range[0]; codepoint <= src_range[1]; codepoint++)
02844             {
02845                 if (dst_tmp.GlyphsSet.TestBit(codepoint))    // Don't overwrite existing glyphs. We could make this an option for MergeMode (e.g. MergeOverwrite==true)
02846                     continue;
02847                 if (!stbtt_FindGlyphIndex(&src_tmp.FontInfo, codepoint))    // It is actually in the font?
02848                     continue;
02849 
02850                 // Add to avail set/counters
02851                 src_tmp.GlyphsCount++;
02852                 dst_tmp.GlyphsCount++;
02853                 src_tmp.GlyphsSet.SetBit(codepoint);
02854                 dst_tmp.GlyphsSet.SetBit(codepoint);
02855                 total_glyphs_count++;
02856             }
02857     }
02858 
02859     // 3. Unpack our bit map into a flat list (we now have all the Unicode points that we know are requested _and_ available _and_ not overlapping another)
02860     for (int src_i = 0; src_i < src_tmp_array.Size; src_i++)
02861     {
02862         ImFontBuildSrcData& src_tmp = src_tmp_array[src_i];
02863         src_tmp.GlyphsList.reserve(src_tmp.GlyphsCount);
02864         UnpackBitVectorToFlatIndexList(&src_tmp.GlyphsSet, &src_tmp.GlyphsList);
02865         src_tmp.GlyphsSet.Clear();
02866         IM_ASSERT(src_tmp.GlyphsList.Size == src_tmp.GlyphsCount);
02867     }
02868     for (int dst_i = 0; dst_i < dst_tmp_array.Size; dst_i++)
02869         dst_tmp_array[dst_i].GlyphsSet.Clear();
02870     dst_tmp_array.clear();
02871 
02872     // Allocate packing character data and flag packed characters buffer as non-packed (x0=y0=x1=y1=0)
02873     // (We technically don't need to zero-clear buf_rects, but let's do it for the sake of sanity)
02874     ImVector<stbrp_rect> buf_rects;
02875     ImVector<stbtt_packedchar> buf_packedchars;
02876     buf_rects.resize(total_glyphs_count);
02877     buf_packedchars.resize(total_glyphs_count);
02878     memset(buf_rects.Data, 0, (size_t)buf_rects.size_in_bytes());
02879     memset(buf_packedchars.Data, 0, (size_t)buf_packedchars.size_in_bytes());
02880 
02881     // 4. Gather glyphs sizes so we can pack them in our virtual canvas.
02882     int total_surface = 0;
02883     int buf_rects_out_n = 0;
02884     int buf_packedchars_out_n = 0;
02885     for (int src_i = 0; src_i < src_tmp_array.Size; src_i++)
02886     {
02887         ImFontBuildSrcData& src_tmp = src_tmp_array[src_i];
02888         if (src_tmp.GlyphsCount == 0)
02889             continue;
02890 
02891         src_tmp.Rects = &buf_rects[buf_rects_out_n];
02892         src_tmp.PackedChars = &buf_packedchars[buf_packedchars_out_n];
02893         buf_rects_out_n += src_tmp.GlyphsCount;
02894         buf_packedchars_out_n += src_tmp.GlyphsCount;
02895 
02896         // Convert our ranges in the format stb_truetype wants
02897         ImFontConfig& cfg = atlas->ConfigData[src_i];
02898         src_tmp.PackRange.font_size = cfg.SizePixels * cfg.RasterizerDensity;
02899         src_tmp.PackRange.first_unicode_codepoint_in_range = 0;
02900         src_tmp.PackRange.array_of_unicode_codepoints = src_tmp.GlyphsList.Data;
02901         src_tmp.PackRange.num_chars = src_tmp.GlyphsList.Size;
02902         src_tmp.PackRange.chardata_for_range = src_tmp.PackedChars;
02903         src_tmp.PackRange.h_oversample = (unsigned char)cfg.OversampleH;
02904         src_tmp.PackRange.v_oversample = (unsigned char)cfg.OversampleV;
02905 
02906         // Gather the sizes of all rectangles we will need to pack (this loop is based on stbtt_PackFontRangesGatherRects)
02907         const float scale = (cfg.SizePixels > 0.0f) ? stbtt_ScaleForPixelHeight(&src_tmp.FontInfo, cfg.SizePixels * cfg.RasterizerDensity) : stbtt_ScaleForMappingEmToPixels(&src_tmp.FontInfo, -cfg.SizePixels * cfg.RasterizerDensity);
02908         const int padding = atlas->TexGlyphPadding;
02909         for (int glyph_i = 0; glyph_i < src_tmp.GlyphsList.Size; glyph_i++)
02910         {
02911             int x0, y0, x1, y1;
02912             const int glyph_index_in_font = stbtt_FindGlyphIndex(&src_tmp.FontInfo, src_tmp.GlyphsList[glyph_i]);
02913             IM_ASSERT(glyph_index_in_font != 0);
02914             stbtt_GetGlyphBitmapBoxSubpixel(&src_tmp.FontInfo, glyph_index_in_font, scale * cfg.OversampleH, scale * cfg.OversampleV, 0, 0, &x0, &y0, &x1, &y1);
02915             src_tmp.Rects[glyph_i].w = (stbrp_coord)(x1 - x0 + padding + cfg.OversampleH - 1);
02916             src_tmp.Rects[glyph_i].h = (stbrp_coord)(y1 - y0 + padding + cfg.OversampleV - 1);
02917             total_surface += src_tmp.Rects[glyph_i].w * src_tmp.Rects[glyph_i].h;
02918         }
02919     }
02920 
02921     // We need a width for the skyline algorithm, any width!
02922     // The exact width doesn't really matter much, but some API/GPU have texture size limitations and increasing width can decrease height.
02923     // User can override TexDesiredWidth and TexGlyphPadding if they wish, otherwise we use a simple heuristic to select the width based on expected surface.
02924     const int surface_sqrt = (int)ImSqrt((float)total_surface) + 1;
02925     atlas->TexHeight = 0;
02926     if (atlas->TexDesiredWidth > 0)
02927         atlas->TexWidth = atlas->TexDesiredWidth;
02928     else
02929         atlas->TexWidth = (surface_sqrt >= 4096 * 0.7f) ? 4096 : (surface_sqrt >= 2048 * 0.7f) ? 2048 : (surface_sqrt >= 1024 * 0.7f) ? 1024 : 512;
02930 
02931     // 5. Start packing
02932     // Pack our extra data rectangles first, so it will be on the upper-left corner of our texture (UV will have small values).
02933     const int TEX_HEIGHT_MAX = 1024 * 32;
02934     stbtt_pack_context spc = {};
02935     stbtt_PackBegin(&spc, NULL, atlas->TexWidth, TEX_HEIGHT_MAX, 0, atlas->TexGlyphPadding, NULL);
02936     ImFontAtlasBuildPackCustomRects(atlas, spc.pack_info);
02937 
02938     // 6. Pack each source font. No rendering yet, we are working with rectangles in an infinitely tall texture at this point.
02939     for (int src_i = 0; src_i < src_tmp_array.Size; src_i++)
02940     {
02941         ImFontBuildSrcData& src_tmp = src_tmp_array[src_i];
02942         if (src_tmp.GlyphsCount == 0)
02943             continue;
02944 
02945         stbrp_pack_rects((stbrp_context*)spc.pack_info, src_tmp.Rects, src_tmp.GlyphsCount);
02946 
02947         // Extend texture height and mark missing glyphs as non-packed so we won't render them.
02948         // FIXME: We are not handling packing failure here (would happen if we got off TEX_HEIGHT_MAX or if a single if larger than TexWidth?)
02949         for (int glyph_i = 0; glyph_i < src_tmp.GlyphsCount; glyph_i++)
02950             if (src_tmp.Rects[glyph_i].was_packed)
02951                 atlas->TexHeight = ImMax(atlas->TexHeight, src_tmp.Rects[glyph_i].y + src_tmp.Rects[glyph_i].h);
02952     }
02953 
02954     // 7. Allocate texture
02955     atlas->TexHeight = (atlas->Flags & ImFontAtlasFlags_NoPowerOfTwoHeight) ? (atlas->TexHeight + 1) : ImUpperPowerOfTwo(atlas->TexHeight);
02956     atlas->TexUvScale = ImVec2(1.0f / atlas->TexWidth, 1.0f / atlas->TexHeight);
02957     atlas->TexPixelsAlpha8 = (unsigned char*)IM_ALLOC(atlas->TexWidth * atlas->TexHeight);
02958     memset(atlas->TexPixelsAlpha8, 0, atlas->TexWidth * atlas->TexHeight);
02959     spc.pixels = atlas->TexPixelsAlpha8;
02960     spc.height = atlas->TexHeight;
02961 
02962     // 8. Render/rasterize font characters into the texture
02963     for (int src_i = 0; src_i < src_tmp_array.Size; src_i++)
02964     {
02965         ImFontConfig& cfg = atlas->ConfigData[src_i];
02966         ImFontBuildSrcData& src_tmp = src_tmp_array[src_i];
02967         if (src_tmp.GlyphsCount == 0)
02968             continue;
02969 
02970         stbtt_PackFontRangesRenderIntoRects(&spc, &src_tmp.FontInfo, &src_tmp.PackRange, 1, src_tmp.Rects);
02971 
02972         // Apply multiply operator
02973         if (cfg.RasterizerMultiply != 1.0f)
02974         {
02975             unsigned char multiply_table[256];
02976             ImFontAtlasBuildMultiplyCalcLookupTable(multiply_table, cfg.RasterizerMultiply);
02977             stbrp_rect* r = &src_tmp.Rects[0];
02978             for (int glyph_i = 0; glyph_i < src_tmp.GlyphsCount; glyph_i++, r++)
02979                 if (r->was_packed)
02980                     ImFontAtlasBuildMultiplyRectAlpha8(multiply_table, atlas->TexPixelsAlpha8, r->x, r->y, r->w, r->h, atlas->TexWidth * 1);
02981         }
02982         src_tmp.Rects = NULL;
02983     }
02984 
02985     // End packing
02986     stbtt_PackEnd(&spc);
02987     buf_rects.clear();
02988 
02989     // 9. Setup ImFont and glyphs for runtime
02990     for (int src_i = 0; src_i < src_tmp_array.Size; src_i++)
02991     {
02992         // When merging fonts with MergeMode=true:
02993         // - We can have multiple input fonts writing into a same destination font.
02994         // - dst_font->ConfigData is != from cfg which is our source configuration.
02995         ImFontBuildSrcData& src_tmp = src_tmp_array[src_i];
02996         ImFontConfig& cfg = atlas->ConfigData[src_i];
02997         ImFont* dst_font = cfg.DstFont;
02998 
02999         const float font_scale = stbtt_ScaleForPixelHeight(&src_tmp.FontInfo, cfg.SizePixels);
03000         int unscaled_ascent, unscaled_descent, unscaled_line_gap;
03001         stbtt_GetFontVMetrics(&src_tmp.FontInfo, &unscaled_ascent, &unscaled_descent, &unscaled_line_gap);
03002 
03003         const float ascent = ImCeil(unscaled_ascent * font_scale);
03004         const float descent = ImFloor(unscaled_descent * font_scale);
03005         ImFontAtlasBuildSetupFont(atlas, dst_font, &cfg, ascent, descent);
03006         const float font_off_x = cfg.GlyphOffset.x;
03007         const float font_off_y = cfg.GlyphOffset.y + IM_ROUND(dst_font->Ascent);
03008 
03009         const float inv_rasterization_scale = 1.0f / cfg.RasterizerDensity;
03010 
03011         for (int glyph_i = 0; glyph_i < src_tmp.GlyphsCount; glyph_i++)
03012         {
03013             // Register glyph
03014             const int codepoint = src_tmp.GlyphsList[glyph_i];
03015             const stbtt_packedchar& pc = src_tmp.PackedChars[glyph_i];
03016             stbtt_aligned_quad q;
03017             float unused_x = 0.0f, unused_y = 0.0f;
03018             stbtt_GetPackedQuad(src_tmp.PackedChars, atlas->TexWidth, atlas->TexHeight, glyph_i, &unused_x, &unused_y, &q, 0);
03019             float x0 = q.x0 * inv_rasterization_scale + font_off_x;
03020             float y0 = q.y0 * inv_rasterization_scale + font_off_y;
03021             float x1 = q.x1 * inv_rasterization_scale + font_off_x;
03022             float y1 = q.y1 * inv_rasterization_scale + font_off_y;
03023             dst_font->AddGlyph(&cfg, (ImWchar)codepoint, x0, y0, x1, y1, q.s0, q.t0, q.s1, q.t1, pc.xadvance * inv_rasterization_scale);
03024         }
03025     }
03026 
03027     // Cleanup
03028     src_tmp_array.clear_destruct();
03029 
03030     ImFontAtlasBuildFinish(atlas);
03031     return true;
03032 }
