03120 static void ImFontAtlasBuildRenderDefaultTexData(ImFontAtlas* atlas)
03121 {
03122     ImFontAtlasCustomRect* r = atlas->GetCustomRectByIndex(atlas->PackIdMouseCursors);
03123     IM_ASSERT(r->IsPacked());
03124 
03125     const int w = atlas->TexWidth;
03126     if (!(atlas->Flags & ImFontAtlasFlags_NoMouseCursors))
03127     {
03128         // Render/copy pixels
03129         IM_ASSERT(r->Width == FONT_ATLAS_DEFAULT_TEX_DATA_W * 2 + 1 && r->Height == FONT_ATLAS_DEFAULT_TEX_DATA_H);
03130         const int x_for_white = r->X;
03131         const int x_for_black = r->X + FONT_ATLAS_DEFAULT_TEX_DATA_W + 1;
03132         if (atlas->TexPixelsAlpha8 != NULL)
03133         {
03134             ImFontAtlasBuildRender8bppRectFromString(atlas, x_for_white, r->Y, FONT_ATLAS_DEFAULT_TEX_DATA_W, FONT_ATLAS_DEFAULT_TEX_DATA_H, FONT_ATLAS_DEFAULT_TEX_DATA_PIXELS, '.', 0xFF);
03135             ImFontAtlasBuildRender8bppRectFromString(atlas, x_for_black, r->Y, FONT_ATLAS_DEFAULT_TEX_DATA_W, FONT_ATLAS_DEFAULT_TEX_DATA_H, FONT_ATLAS_DEFAULT_TEX_DATA_PIXELS, 'X', 0xFF);
03136         }
03137         else
03138         {
03139             ImFontAtlasBuildRender32bppRectFromString(atlas, x_for_white, r->Y, FONT_ATLAS_DEFAULT_TEX_DATA_W, FONT_ATLAS_DEFAULT_TEX_DATA_H, FONT_ATLAS_DEFAULT_TEX_DATA_PIXELS, '.', IM_COL32_WHITE);
03140             ImFontAtlasBuildRender32bppRectFromString(atlas, x_for_black, r->Y, FONT_ATLAS_DEFAULT_TEX_DATA_W, FONT_ATLAS_DEFAULT_TEX_DATA_H, FONT_ATLAS_DEFAULT_TEX_DATA_PIXELS, 'X', IM_COL32_WHITE);
03141         }
03142     }
03143     else
03144     {
03145         // Render 4 white pixels
03146         IM_ASSERT(r->Width == 2 && r->Height == 2);
03147         const int offset = (int)r->X + (int)r->Y * w;
03148         if (atlas->TexPixelsAlpha8 != NULL)
03149         {
03150             atlas->TexPixelsAlpha8[offset] = atlas->TexPixelsAlpha8[offset + 1] = atlas->TexPixelsAlpha8[offset + w] = atlas->TexPixelsAlpha8[offset + w + 1] = 0xFF;
03151         }
03152         else
03153         {
03154             atlas->TexPixelsRGBA32[offset] = atlas->TexPixelsRGBA32[offset + 1] = atlas->TexPixelsRGBA32[offset + w] = atlas->TexPixelsRGBA32[offset + w + 1] = IM_COL32_WHITE;
03155         }
03156     }
03157     atlas->TexUvWhitePixel = ImVec2((r->X + 0.5f) * atlas->TexUvScale.x, (r->Y + 0.5f) * atlas->TexUvScale.y);
03158 }
03159 
03160 static void ImFontAtlasBuildRenderLinesTexData(ImFontAtlas* atlas)
03161 {
03162     if (atlas->Flags & ImFontAtlasFlags_NoBakedLines)
03163         return;
03164 
03165     // This generates a triangular shape in the texture, with the various line widths stacked on top of each other to allow interpolation between them
03166     ImFontAtlasCustomRect* r = atlas->GetCustomRectByIndex(atlas->PackIdLines);
03167     IM_ASSERT(r->IsPacked());
03168     for (unsigned int n = 0; n < IM_DRAWLIST_TEX_LINES_WIDTH_MAX + 1; n++) // +1 because of the zero-width row
03169     {
03170         // Each line consists of at least two empty pixels at the ends, with a line of solid pixels in the middle
03171         unsigned int y = n;
03172         unsigned int line_width = n;
03173         unsigned int pad_left = (r->Width - line_width) / 2;
03174         unsigned int pad_right = r->Width - (pad_left + line_width);
03175 
03176         // Write each slice
03177         IM_ASSERT(pad_left + line_width + pad_right == r->Width && y < r->Height); // Make sure we're inside the texture bounds before we start writing pixels
03178         if (atlas->TexPixelsAlpha8 != NULL)
03179         {
03180             unsigned char* write_ptr = &atlas->TexPixelsAlpha8[r->X + ((r->Y + y) * atlas->TexWidth)];
03181             for (unsigned int i = 0; i < pad_left; i++)
03182                 *(write_ptr + i) = 0x00;
03183 
03184             for (unsigned int i = 0; i < line_width; i++)
03185                 *(write_ptr + pad_left + i) = 0xFF;
03186 
03187             for (unsigned int i = 0; i < pad_right; i++)
03188                 *(write_ptr + pad_left + line_width + i) = 0x00;
03189         }
03190         else
03191         {
03192             unsigned int* write_ptr = &atlas->TexPixelsRGBA32[r->X + ((r->Y + y) * atlas->TexWidth)];
03193             for (unsigned int i = 0; i < pad_left; i++)
03194                 *(write_ptr + i) = IM_COL32(255, 255, 255, 0);
03195 
03196             for (unsigned int i = 0; i < line_width; i++)
03197                 *(write_ptr + pad_left + i) = IM_COL32_WHITE;
03198 
03199             for (unsigned int i = 0; i < pad_right; i++)
03200                 *(write_ptr + pad_left + line_width + i) = IM_COL32(255, 255, 255, 0);
03201         }
03202 
03203         // Calculate UVs for this line
03204         ImVec2 uv0 = ImVec2((float)(r->X + pad_left - 1), (float)(r->Y + y)) * atlas->TexUvScale;
03205         ImVec2 uv1 = ImVec2((float)(r->X + pad_left + line_width + 1), (float)(r->Y + y + 1)) * atlas->TexUvScale;
03206         float half_v = (uv0.y + uv1.y) * 0.5f; // Calculate a constant V in the middle of the row to avoid sampling artifacts
03207         atlas->TexUvLines[n] = ImVec4(uv0.x, half_v, uv1.x, half_v);
03208     }
03209 }
03210 
03211 // Note: this is called / shared by both the stb_truetype and the FreeType builder
03212 void ImFontAtlasBuildInit(ImFontAtlas* atlas)
03213 {
03214     // Round font size
03215     // - We started rounding in 1.90 WIP (18991) as our layout system currently doesn't support non-rounded font size well yet.
03216     // - Note that using io.FontGlobalScale or SetWindowFontScale(), with are legacy-ish, partially supported features, can still lead to unrounded sizes.
03217     // - We may support it better later and remove this rounding.
03218     for (ImFontConfig& cfg : atlas->ConfigData)
03219        cfg.SizePixels = ImTrunc(cfg.SizePixels);
03220 
03221     // Register texture region for mouse cursors or standard white pixels
03222     if (atlas->PackIdMouseCursors < 0)
03223     {
03224         if (!(atlas->Flags & ImFontAtlasFlags_NoMouseCursors))
03225             atlas->PackIdMouseCursors = atlas->AddCustomRectRegular(FONT_ATLAS_DEFAULT_TEX_DATA_W * 2 + 1, FONT_ATLAS_DEFAULT_TEX_DATA_H);
03226         else
03227             atlas->PackIdMouseCursors = atlas->AddCustomRectRegular(2, 2);
03228     }
03229 
03230     // Register texture region for thick lines
03231     // The +2 here is to give space for the end caps, whilst height +1 is to accommodate the fact we have a zero-width row
03232     if (atlas->PackIdLines < 0)
03233     {
03234         if (!(atlas->Flags & ImFontAtlasFlags_NoBakedLines))
03235             atlas->PackIdLines = atlas->AddCustomRectRegular(IM_DRAWLIST_TEX_LINES_WIDTH_MAX + 2, IM_DRAWLIST_TEX_LINES_WIDTH_MAX + 1);
03236     }
03237 }
03238 
03239 // This is called/shared by both the stb_truetype and the FreeType builder.
03240 void ImFontAtlasBuildFinish(ImFontAtlas* atlas)
03241 {
03242     // Render into our custom data blocks
03243     IM_ASSERT(atlas->TexPixelsAlpha8 != NULL || atlas->TexPixelsRGBA32 != NULL);
03244     ImFontAtlasBuildRenderDefaultTexData(atlas);
03245     ImFontAtlasBuildRenderLinesTexData(atlas);
03246 
03247     // Register custom rectangle glyphs
03248     for (int i = 0; i < atlas->CustomRects.Size; i++)
03249     {
03250         const ImFontAtlasCustomRect* r = &atlas->CustomRects[i];
03251         if (r->Font == NULL || r->GlyphID == 0)
03252             continue;
03253 
03254         // Will ignore ImFontConfig settings: GlyphMinAdvanceX, GlyphMinAdvanceY, GlyphExtraSpacing, PixelSnapH
03255         IM_ASSERT(r->Font->ContainerAtlas == atlas);
03256         ImVec2 uv0, uv1;
03257         atlas->CalcCustomRectUV(r, &uv0, &uv1);
03258         r->Font->AddGlyph(NULL, (ImWchar)r->GlyphID, r->GlyphOffset.x, r->GlyphOffset.y, r->GlyphOffset.x + r->Width, r->GlyphOffset.y + r->Height, uv0.x, uv0.y, uv1.x, uv1.y, r->GlyphAdvanceX);
03259     }
03260 
03261     // Build all fonts lookup tables
03262     for (ImFont* font : atlas->Fonts)
03263         if (font->DirtyLookupTables)
03264             font->BuildLookupTable();
03265 
03266     atlas->TexReady = true;
03267 }
