03320 static void UnpackAccumulativeOffsetsIntoRanges(int base_codepoint, const short* accumulative_offsets, int accumulative_offsets_count, ImWchar* out_ranges)
03321 {
03322     for (int n = 0; n < accumulative_offsets_count; n++, out_ranges += 2)
03323     {
03324         out_ranges[0] = out_ranges[1] = (ImWchar)(base_codepoint + accumulative_offsets[n]);
03325         base_codepoint += accumulative_offsets[n];
03326     }
03327     out_ranges[0] = 0;
03328 }
