03538 void ImFontGlyphRangesBuilder::AddText(const char* text, const char* text_end)
03539 {
03540     while (text_end ? (text < text_end) : *text)
03541     {
03542         unsigned int c = 0;
03543         int c_len = ImTextCharFromUtf8(&c, text, text_end);
03544         text += c_len;
03545         if (c_len == 0)
03546             break;
03547         AddChar((ImWchar)c);
03548     }
03549 }
