03551 void ImFontGlyphRangesBuilder::AddRanges(const ImWchar* ranges)
03552 {
03553     for (; ranges[0]; ranges += 2)
03554         for (unsigned int c = ranges[0]; c <= ranges[1] && c <= IM_UNICODE_CODEPOINT_MAX; c++) //-V560
03555             AddChar((ImWchar)c);
03556 }
