03558 void ImFontGlyphRangesBuilder::BuildRanges(ImVector<ImWchar>* out_ranges)
03559 {
03560     const int max_codepoint = IM_UNICODE_CODEPOINT_MAX;
03561     for (int n = 0; n <= max_codepoint; n++)
03562         if (GetBit(n))
03563         {
03564             out_ranges->push_back((ImWchar)n);
03565             while (n < max_codepoint && GetBit(n + 1))
03566                 n++;
03567             out_ranges->push_back((ImWchar)n);
03568         }
03569     out_ranges->push_back(0);
03570 }
