03605     IndexAdvanceX.clear();
03606     IndexLookup.clear();
03607     FallbackGlyph = NULL;
03608     ContainerAtlas = NULL;
03609     DirtyLookupTables = true;
03610     Ascent = Descent = 0.0f;
03611     MetricsTotalSurface = 0;
03612 }
03613 
03614 static ImWchar FindFirstExistingGlyph(ImFont* font, const ImWchar* candidate_chars, int candidate_chars_count)
03615 {
03616     for (int n = 0; n < candidate_chars_count; n++)
03617         if (font->FindGlyphNoFallback(candidate_chars[n]) != NULL)
03618             return candidate_chars[n];
03619     return (ImWchar)-1;
03620 }
03621 
03622 void ImFont::BuildLookupTable()
03623 {
03624     int max_codepoint = 0;
03625     for (int i = 0; i != Glyphs.Size; i++)
03626         max_codepoint = ImMax(max_codepoint, (int)Glyphs[i].Codepoint);
03627 
03628     // Build lookup table
03629     IM_ASSERT(Glyphs.Size > 0 && "Font has not loaded glyph!");
03630     IM_ASSERT(Glyphs.Size < 0xFFFF); // -1 is reserved
03631     IndexAdvanceX.clear();
03632     IndexLookup.clear();
03633     DirtyLookupTables = false;
03634     memset(Used4kPagesMap, 0, sizeof(Used4kPagesMap));
03635     GrowIndex(max_codepoint + 1);
03636     for (int i = 0; i < Glyphs.Size; i++)
03637     {
03638         int codepoint = (int)Glyphs[i].Codepoint;
03639         IndexAdvanceX[codepoint] = Glyphs[i].AdvanceX;
03640         IndexLookup[codepoint] = (ImWchar)i;
03641 
03642         // Mark 4K page as used
03643         const int page_n = codepoint / 4096;
03644         Used4kPagesMap[page_n >> 3] |= 1 << (page_n & 7);
03645     }
03646 
03647     // Create a glyph to handle TAB
03648     // FIXME: Needs proper TAB handling but it needs to be contextualized (or we could arbitrary say that each string starts at "column 0" ?)
03649     if (FindGlyph((ImWchar)' '))
03650     {
03651         if (Glyphs.back().Codepoint != '\t')   // So we can call this function multiple times (FIXME: Flaky)
03652             Glyphs.resize(Glyphs.Size + 1);
03653         ImFontGlyph& tab_glyph = Glyphs.back();
03654         tab_glyph = *FindGlyph((ImWchar)' ');
03655         tab_glyph.Codepoint = '\t';
03656         tab_glyph.AdvanceX *= IM_TABSIZE;
03657         IndexAdvanceX[(int)tab_glyph.Codepoint] = (float)tab_glyph.AdvanceX;
03658         IndexLookup[(int)tab_glyph.Codepoint] = (ImWchar)(Glyphs.Size - 1);
03659     }
03660 
03661     // Mark special glyphs as not visible (note that AddGlyph already mark as non-visible glyphs with zero-size polygons)
03662     SetGlyphVisible((ImWchar)' ', false);
03663     SetGlyphVisible((ImWchar)'\t', false);
03664 
03665     // Setup Fallback character
03666     const ImWchar fallback_chars[] = { (ImWchar)IM_UNICODE_CODEPOINT_INVALID, (ImWchar)'?', (ImWchar)' ' };
03667     FallbackGlyph = FindGlyphNoFallback(FallbackChar);
03668     if (FallbackGlyph == NULL)
03669     {
03670         FallbackChar = FindFirstExistingGlyph(this, fallback_chars, IM_ARRAYSIZE(fallback_chars));
03671         FallbackGlyph = FindGlyphNoFallback(FallbackChar);
03672         if (FallbackGlyph == NULL)
03673         {
03674             FallbackGlyph = &Glyphs.back();
03675             FallbackChar = (ImWchar)FallbackGlyph->Codepoint;
03676         }
03677     }
03678     FallbackAdvanceX = FallbackGlyph->AdvanceX;
03679     for (int i = 0; i < max_codepoint + 1; i++)
03680         if (IndexAdvanceX[i] < 0.0f)
03681             IndexAdvanceX[i] = FallbackAdvanceX;
03682 
03683     // Setup Ellipsis character. It is required for rendering elided text. We prefer using U+2026 (horizontal ellipsis).
03684     // However some old fonts may contain ellipsis at U+0085. Here we auto-detect most suitable ellipsis character.
03685     // FIXME: Note that 0x2026 is rarely included in our font ranges. Because of this we are more likely to use three individual dots.
03686     const ImWchar ellipsis_chars[] = { (ImWchar)0x2026, (ImWchar)0x0085 };
03687     const ImWchar dots_chars[] = { (ImWchar)'.', (ImWchar)0xFF0E };
03688     if (EllipsisChar == (ImWchar)-1)
03689         EllipsisChar = FindFirstExistingGlyph(this, ellipsis_chars, IM_ARRAYSIZE(ellipsis_chars));
03690     const ImWchar dot_char = FindFirstExistingGlyph(this, dots_chars, IM_ARRAYSIZE(dots_chars));
03691     if (EllipsisChar != (ImWchar)-1)
03692     {
03693         EllipsisCharCount = 1;
03694         EllipsisWidth = EllipsisCharStep = FindGlyph(EllipsisChar)->X1;
03695     }
03696     else if (dot_char != (ImWchar)-1)
03697     {
03698         const ImFontGlyph* glyph = FindGlyph(dot_char);
03699         EllipsisChar = dot_char;
03700         EllipsisCharCount = 3;
03701         EllipsisCharStep = (glyph->X1 - glyph->X0) + 1.0f;
03702         EllipsisWidth = EllipsisCharStep * 3.0f - 1.0f;
03703     }
03704 }
03705 
03706 // API is designed this way to avoid exposing the 4K page size
03707 // e.g. use with IsGlyphRangeUnused(0, 255)
03708 bool ImFont::IsGlyphRangeUnused(unsigned int c_begin, unsigned int c_last)
03709 {
03710     unsigned int page_begin = (c_begin / 4096);
03711     unsigned int page_last = (c_last / 4096);
03712     for (unsigned int page_n = page_begin; page_n <= page_last; page_n++)
03713         if ((page_n >> 3) < sizeof(Used4kPagesMap))
03714             if (Used4kPagesMap[page_n >> 3] & (1 << (page_n & 7)))
03715                 return false;
03716     return true;
03717 }
03718 
03719 void ImFont::SetGlyphVisible(ImWchar c, bool visible)
03720 {
03721     if (ImFontGlyph* glyph = (ImFontGlyph*)(void*)FindGlyph((ImWchar)c))
03722         glyph->Visible = visible ? 1 : 0;
03723 }
03724 
03725 void ImFont::GrowIndex(int new_size)
03726 {
03727     IM_ASSERT(IndexAdvanceX.Size == IndexLookup.Size);
03728     if (new_size <= IndexLookup.Size)
03729         return;
03730     IndexAdvanceX.resize(new_size, -1.0f);
03731     IndexLookup.resize(new_size, (ImWchar)-1);
03732 }
03733 
03734 // x0/y0/x1/y1 are offset from the character upper-left layout position, in pixels. Therefore x0/y0 are often fairly close to zero.
03735 // Not to be mistaken with texture coordinates, which are held by u0/v0/u1/v1 in normalized format (0.0..1.0 on each texture axis).
03736 // 'cfg' is not necessarily == 'this->ConfigData' because multiple source fonts+configs can be used to build one target font.
03737 void ImFont::AddGlyph(const ImFontConfig* cfg, ImWchar codepoint, float x0, float y0, float x1, float y1, float u0, float v0, float u1, float v1, float advance_x)
03738 {
03739     if (cfg != NULL)
03740     {
03741         // Clamp & recenter if needed
03742         const float advance_x_original = advance_x;
03743         advance_x = ImClamp(advance_x, cfg->GlyphMinAdvanceX, cfg->GlyphMaxAdvanceX);
03744         if (advance_x != advance_x_original)
03745         {
03746             float char_off_x = cfg->PixelSnapH ? ImTrunc((advance_x - advance_x_original) * 0.5f) : (advance_x - advance_x_original) * 0.5f;
03747             x0 += char_off_x;
03748             x1 += char_off_x;
03749         }
03750 
03751         // Snap to pixel
03752         if (cfg->PixelSnapH)
03753             advance_x = IM_ROUND(advance_x);
03754 
03755         // Bake spacing
03756         advance_x += cfg->GlyphExtraSpacing.x;
03757     }
03758 
03759     Glyphs.resize(Glyphs.Size + 1);
03760     ImFontGlyph& glyph = Glyphs.back();
03761     glyph.Codepoint = (unsigned int)codepoint;
03762     glyph.Visible = (x0 != x1) && (y0 != y1);
03763     glyph.Colored = false;
03764     glyph.X0 = x0;
03765     glyph.Y0 = y0;
03766     glyph.X1 = x1;
03767     glyph.Y1 = y1;
03768     glyph.U0 = u0;
03769     glyph.V0 = v0;
03770     glyph.U1 = u1;
03771     glyph.V1 = v1;
03772     glyph.AdvanceX = advance_x;
03773 
03774     // Compute rough surface usage metrics (+1 to account for average padding, +0.99 to round)
03775     // We use (U1-U0)*TexWidth instead of X1-X0 to account for oversampling.
03776     float pad = ContainerAtlas->TexGlyphPadding + 0.99f;
03777     DirtyLookupTables = true;
03778     MetricsTotalSurface += (int)((glyph.U1 - glyph.U0) * ContainerAtlas->TexWidth + pad) * (int)((glyph.V1 - glyph.V0) * ContainerAtlas->TexHeight + pad);
03779 }
03780 
03781 void ImFont::AddRemapChar(ImWchar dst, ImWchar src, bool overwrite_dst)
03782 {
03783     IM_ASSERT(IndexLookup.Size > 0);    // Currently this can only be called AFTER the font has been built, aka after calling ImFontAtlas::GetTexDataAs*() function.
03784     unsigned int index_size = (unsigned int)IndexLookup.Size;
03785 
03786     if (dst < index_size && IndexLookup.Data[dst] == (ImWchar)-1 && !overwrite_dst) // 'dst' already exists
03787         return;
03788     if (src >= index_size && dst >= index_size) // both 'dst' and 'src' don't exist -> no-op
03789         return;
03790 
03791     GrowIndex(dst + 1);
03792     IndexLookup[dst] = (src < index_size) ? IndexLookup.Data[src] : (ImWchar)-1;
03793     IndexAdvanceX[dst] = (src < index_size) ? IndexAdvanceX.Data[src] : 1.0f;
03794 }
03795 
03796 const ImFontGlyph* ImFont::FindGlyph(ImWchar c) const
03797 {
03798     if (c >= (size_t)IndexLookup.Size)
03799         return FallbackGlyph;
03800     const ImWchar i = IndexLookup.Data[c];
03801     if (i == (ImWchar)-1)
03802         return FallbackGlyph;
03803     return &Glyphs.Data[i];
03804 }
03805 
03806 const ImFontGlyph* ImFont::FindGlyphNoFallback(ImWchar c) const
03807 {
03808     if (c >= (size_t)IndexLookup.Size)
03809         return NULL;
03810     const ImWchar i = IndexLookup.Data[c];
03811     if (i == (ImWchar)-1)
03812         return NULL;
03813     return &Glyphs.Data[i];
03814 }
03815 
03816 // Wrapping skips upcoming blanks
03817 static inline const char* CalcWordWrapNextLineStartA(const char* text, const char* text_end)
03818 {
03819     while (text < text_end && ImCharIsBlankA(*text))
03820         text++;
03821     if (*text == '\n')
03822         text++;
03823     return text;
03824 }
03825 
03826 // Simple word-wrapping for English, not full-featured. Please submit failing cases!
03827 // This will return the next location to wrap from. If no wrapping if necessary, this will fast-forward to e.g. text_end.
03828 // FIXME: Much possible improvements (don't cut things like "word !", "word!!!" but cut within "word,,,,", more sensible support for punctuations, support for Unicode punctuations, etc.)
03829 const char* ImFont::CalcWordWrapPositionA(float scale, const char* text, const char* text_end, float wrap_width) const
03830 {
03831     // For references, possible wrap point marked with ^
03832     //  "aaa bbb, ccc,ddd. eee   fff. ggg!"
03833     //      ^    ^    ^   ^   ^__    ^    ^
03834 
03835     // List of hardcoded separators: .,;!?'"
03836 
03837     // Skip extra blanks after a line returns (that includes not counting them in width computation)
03838     // e.g. "Hello    world" --> "Hello" "World"
03839 
03840     // Cut words that cannot possibly fit within one line.
03841     // e.g.: "The tropical fish" with ~5 characters worth of width --> "The tr" "opical" "fish"
03842     float line_width = 0.0f;
03843     float word_width = 0.0f;
03844     float blank_width = 0.0f;
03845     wrap_width /= scale; // We work with unscaled widths to avoid scaling every characters
03846 
03847     const char* word_end = text;
03848     const char* prev_word_end = NULL;
03849     bool inside_word = true;
03850 
03851     const char* s = text;
03852     IM_ASSERT(text_end != NULL);
03853     while (s < text_end)
03854     {
03855         unsigned int c = (unsigned int)*s;
03856         const char* next_s;
03857         if (c < 0x80)
03858             next_s = s + 1;
03859         else
03860             next_s = s + ImTextCharFromUtf8(&c, s, text_end);
03861 
03862         if (c < 32)
03863         {
03864             if (c == '\n')
03865             {
03866                 line_width = word_width = blank_width = 0.0f;
03867                 inside_word = true;
03868                 s = next_s;
03869                 continue;
03870             }
03871             if (c == '\r')
03872             {
03873                 s = next_s;
03874                 continue;
03875             }
03876         }
03877 
03878         const float char_width = ((int)c < IndexAdvanceX.Size ? IndexAdvanceX.Data[c] : FallbackAdvanceX);
03879         if (ImCharIsBlankW(c))
03880         {
03881             if (inside_word)
03882             {
03883                 line_width += blank_width;
03884                 blank_width = 0.0f;
03885                 word_end = s;
03886             }
03887             blank_width += char_width;
03888             inside_word = false;
03889         }
03890         else
03891         {
03892             word_width += char_width;
03893             if (inside_word)
03894             {
03895                 word_end = next_s;
03896             }
03897             else
03898             {
03899                 prev_word_end = word_end;
03900                 line_width += word_width + blank_width;
03901                 word_width = blank_width = 0.0f;
03902             }
03903 
03904             // Allow wrapping after punctuation.
03905             inside_word = (c != '.' && c != ',' && c != ';' && c != '!' && c != '?' && c != '\"');
03906         }
03907 
03908         // We ignore blank width at the end of the line (they can be skipped)
03909         if (line_width + word_width > wrap_width)
03910         {
03911             // Words that cannot possibly fit within an entire line will be cut anywhere.
03912             if (word_width < wrap_width)
03913                 s = prev_word_end ? prev_word_end : word_end;
03914             break;
03915         }
03916 
03917         s = next_s;
03918     }
03919 
03920     // Wrap_width is too small to fit anything. Force displaying 1 character to minimize the height discontinuity.
03921     // +1 may not be a character start point in UTF-8 but it's ok because caller loops use (text >= word_wrap_eol).
03922     if (s == text && text < text_end)
03923         return s + 1;
03924     return s;
03925 }
03926 
03927 ImVec2 ImFont::CalcTextSizeA(float size, float max_width, float wrap_width, const char* text_begin, const char* text_end, const char** remaining) const
03928 {
03929     if (!text_end)
03930         text_end = text_begin + strlen(text_begin); // FIXME-OPT: Need to avoid this.
03931 
03932     const float line_height = size;
03933     const float scale = size / FontSize;
03934 
03935     ImVec2 text_size = ImVec2(0, 0);
03936     float line_width = 0.0f;
03937 
03938     const bool word_wrap_enabled = (wrap_width > 0.0f);
03939     const char* word_wrap_eol = NULL;
03940 
03941     const char* s = text_begin;
03942     while (s < text_end)
03943     {
03944         if (word_wrap_enabled)
03945         {
03946             // Calculate how far we can render. Requires two passes on the string data but keeps the code simple and not intrusive for what's essentially an uncommon feature.
03947             if (!word_wrap_eol)
03948                 word_wrap_eol = CalcWordWrapPositionA(scale, s, text_end, wrap_width - line_width);
03949 
03950             if (s >= word_wrap_eol)
03951             {
03952                 if (text_size.x < line_width)
03953                     text_size.x = line_width;
03954                 text_size.y += line_height;
03955                 line_width = 0.0f;
03956                 word_wrap_eol = NULL;
03957                 s = CalcWordWrapNextLineStartA(s, text_end); // Wrapping skips upcoming blanks
03958                 continue;
03959             }
03960         }
03961 
03962         // Decode and advance source
03963         const char* prev_s = s;
03964         unsigned int c = (unsigned int)*s;
03965         if (c < 0x80)
03966             s += 1;
03967         else
03968             s += ImTextCharFromUtf8(&c, s, text_end);
03969 
03970         if (c < 32)
03971         {
03972             if (c == '\n')
03973             {
03974                 text_size.x = ImMax(text_size.x, line_width);
03975                 text_size.y += line_height;
03976                 line_width = 0.0f;
03977                 continue;
03978             }
03979             if (c == '\r')
03980                 continue;
03981         }
03982 
03983         const float char_width = ((int)c < IndexAdvanceX.Size ? IndexAdvanceX.Data[c] : FallbackAdvanceX) * scale;
03984         if (line_width + char_width >= max_width)
03985         {
03986             s = prev_s;
03987             break;
03988         }
03989 
03990         line_width += char_width;
03991     }
03992 
03993     if (text_size.x < line_width)
03994         text_size.x = line_width;
03995 
03996     if (line_width > 0 || text_size.y == 0.0f)
03997         text_size.y += line_height;
03998 
03999     if (remaining)
04000         *remaining = s;
04001 
04002     return text_size;
04003 }
04004 
04005 // Note: as with every ImDrawList drawing function, this expects that the font atlas texture is bound.
04006 void ImFont::RenderChar(ImDrawList* draw_list, float size, const ImVec2& pos, ImU32 col, ImWchar c) const
04007 {
04008     const ImFontGlyph* glyph = FindGlyph(c);
04009     if (!glyph || !glyph->Visible)
04010         return;
04011     if (glyph->Colored)
04012         col |= ~IM_COL32_A_MASK;
04013     float scale = (size >= 0.0f) ? (size / FontSize) : 1.0f;
04014     float x = IM_TRUNC(pos.x);
04015     float y = IM_TRUNC(pos.y);
04016     draw_list->PrimReserve(6, 4);
04017     draw_list->PrimRectUV(ImVec2(x + glyph->X0 * scale, y + glyph->Y0 * scale), ImVec2(x + glyph->X1 * scale, y + glyph->Y1 * scale), ImVec2(glyph->U0, glyph->V0), ImVec2(glyph->U1, glyph->V1), col);
04018 }
04019 
04020 // Note: as with every ImDrawList drawing function, this expects that the font atlas texture is bound.
04021 void ImFont::RenderText(ImDrawList* draw_list, float size, const ImVec2& pos, ImU32 col, const ImVec4& clip_rect, const char* text_begin, const char* text_end, float wrap_width, bool cpu_fine_clip) const
04022 {
04023     if (!text_end)
04024         text_end = text_begin + strlen(text_begin); // ImGui:: functions generally already provides a valid text_end, so this is merely to handle direct calls.
04025 
04026     // Align to be pixel perfect
04027     float x = IM_TRUNC(pos.x);
04028     float y = IM_TRUNC(pos.y);
04029     if (y > clip_rect.w)
04030         return;
04031 
04032     const float start_x = x;
04033     const float scale = size / FontSize;
04034     const float line_height = FontSize * scale;
04035     const bool word_wrap_enabled = (wrap_width > 0.0f);
04036 
04037     // Fast-forward to first visible line
04038     const char* s = text_begin;
04039     if (y + line_height < clip_rect.y)
04040         while (y + line_height < clip_rect.y && s < text_end)
04041         {
04042             const char* line_end = (const char*)memchr(s, '\n', text_end - s);
04043             if (word_wrap_enabled)
04044             {
04045                 // FIXME-OPT: This is not optimal as do first do a search for \n before calling CalcWordWrapPositionA().
04046                 // If the specs for CalcWordWrapPositionA() were reworked to optionally return on \n we could combine both.
04047                 // However it is still better than nothing performing the fast-forward!
04048                 s = CalcWordWrapPositionA(scale, s, line_end ? line_end : text_end, wrap_width);
04049                 s = CalcWordWrapNextLineStartA(s, text_end);
04050             }
04051             else
04052             {
04053                 s = line_end ? line_end + 1 : text_end;
04054             }
04055             y += line_height;
04056         }
04057 
04058     // For large text, scan for the last visible line in order to avoid over-reserving in the call to PrimReserve()
04059     // Note that very large horizontal line will still be affected by the issue (e.g. a one megabyte string buffer without a newline will likely crash atm)
04060     if (text_end - s > 10000 && !word_wrap_enabled)
04061     {
04062         const char* s_end = s;
04063         float y_end = y;
04064         while (y_end < clip_rect.w && s_end < text_end)
04065         {
04066             s_end = (const char*)memchr(s_end, '\n', text_end - s_end);
04067             s_end = s_end ? s_end + 1 : text_end;
04068             y_end += line_height;
04069         }
04070         text_end = s_end;
04071     }
04072     if (s == text_end)
04073         return;
04074 
04075     // Reserve vertices for remaining worse case (over-reserving is useful and easily amortized)
04076     const int vtx_count_max = (int)(text_end - s) * 4;
04077     const int idx_count_max = (int)(text_end - s) * 6;
04078     const int idx_expected_size = draw_list->IdxBuffer.Size + idx_count_max;
04079     draw_list->PrimReserve(idx_count_max, vtx_count_max);
04080     ImDrawVert*  vtx_write = draw_list->_VtxWritePtr;
04081     ImDrawIdx*   idx_write = draw_list->_IdxWritePtr;
04082     unsigned int vtx_index = draw_list->_VtxCurrentIdx;
04083 
04084     const ImU32 col_untinted = col | ~IM_COL32_A_MASK;
04085     const char* word_wrap_eol = NULL;
04086 
04087     while (s < text_end)
04088     {
04089         if (word_wrap_enabled)
04090         {
04091             // Calculate how far we can render. Requires two passes on the string data but keeps the code simple and not intrusive for what's essentially an uncommon feature.
04092             if (!word_wrap_eol)
04093                 word_wrap_eol = CalcWordWrapPositionA(scale, s, text_end, wrap_width - (x - start_x));
04094 
04095             if (s >= word_wrap_eol)
04096             {
04097                 x = start_x;
04098                 y += line_height;
04099                 if (y > clip_rect.w)
04100                     break; // break out of main loop
04101                 word_wrap_eol = NULL;
04102                 s = CalcWordWrapNextLineStartA(s, text_end); // Wrapping skips upcoming blanks
04103                 continue;
04104             }
04105         }
04106 
04107         // Decode and advance source
04108         unsigned int c = (unsigned int)*s;
04109         if (c < 0x80)
04110             s += 1;
04111         else
04112             s += ImTextCharFromUtf8(&c, s, text_end);
04113 
04114         if (c < 32)
04115         {
04116             if (c == '\n')
04117             {
04118                 x = start_x;
04119                 y += line_height;
04120                 if (y > clip_rect.w)
04121                     break; // break out of main loop
04122                 continue;
04123             }
04124             if (c == '\r')
04125                 continue;
04126         }
04127 
04128         const ImFontGlyph* glyph = FindGlyph((ImWchar)c);
04129         if (glyph == NULL)
04130             continue;
04131 
04132         float char_width = glyph->AdvanceX * scale;
04133         if (glyph->Visible)
04134         {
04135             // We don't do a second finer clipping test on the Y axis as we've already skipped anything before clip_rect.y and exit once we pass clip_rect.w
04136             float x1 = x + glyph->X0 * scale;
04137             float x2 = x + glyph->X1 * scale;
04138             float y1 = y + glyph->Y0 * scale;
04139             float y2 = y + glyph->Y1 * scale;
04140             if (x1 <= clip_rect.z && x2 >= clip_rect.x)
04141             {
04142                 // Render a character
04143                 float u1 = glyph->U0;
04144                 float v1 = glyph->V0;
04145                 float u2 = glyph->U1;
04146                 float v2 = glyph->V1;
04147 
04148                 // CPU side clipping used to fit text in their frame when the frame is too small. Only does clipping for axis aligned quads.
04149                 if (cpu_fine_clip)
04150                 {
04151                     if (x1 < clip_rect.x)
04152                     {
04153                         u1 = u1 + (1.0f - (x2 - clip_rect.x) / (x2 - x1)) * (u2 - u1);
04154                         x1 = clip_rect.x;
04155                     }
04156                     if (y1 < clip_rect.y)
04157                     {
04158                         v1 = v1 + (1.0f - (y2 - clip_rect.y) / (y2 - y1)) * (v2 - v1);
04159                         y1 = clip_rect.y;
04160                     }
04161                     if (x2 > clip_rect.z)
04162                     {
04163                         u2 = u1 + ((clip_rect.z - x1) / (x2 - x1)) * (u2 - u1);
04164                         x2 = clip_rect.z;
04165                     }
04166                     if (y2 > clip_rect.w)
04167                     {
04168                         v2 = v1 + ((clip_rect.w - y1) / (y2 - y1)) * (v2 - v1);
04169                         y2 = clip_rect.w;
04170                     }
04171                     if (y1 >= y2)
04172                     {
04173                         x += char_width;
04174                         continue;
04175                     }
04176                 }
04177 
04178                 // Support for untinted glyphs
04179                 ImU32 glyph_col = glyph->Colored ? col_untinted : col;
04180 
04181                 // We are NOT calling PrimRectUV() here because non-inlined causes too much overhead in a debug builds. Inlined here:
04182                 {
04183                     vtx_write[0].pos.x = x1; vtx_write[0].pos.y = y1; vtx_write[0].col = glyph_col; vtx_write[0].uv.x = u1; vtx_write[0].uv.y = v1;
04184                     vtx_write[1].pos.x = x2; vtx_write[1].pos.y = y1; vtx_write[1].col = glyph_col; vtx_write[1].uv.x = u2; vtx_write[1].uv.y = v1;
04185                     vtx_write[2].pos.x = x2; vtx_write[2].pos.y = y2; vtx_write[2].col = glyph_col; vtx_write[2].uv.x = u2; vtx_write[2].uv.y = v2;
04186                     vtx_write[3].pos.x = x1; vtx_write[3].pos.y = y2; vtx_write[3].col = glyph_col; vtx_write[3].uv.x = u1; vtx_write[3].uv.y = v2;
04187                     idx_write[0] = (ImDrawIdx)(vtx_index); idx_write[1] = (ImDrawIdx)(vtx_index + 1); idx_write[2] = (ImDrawIdx)(vtx_index + 2);
04188                     idx_write[3] = (ImDrawIdx)(vtx_index); idx_write[4] = (ImDrawIdx)(vtx_index + 2); idx_write[5] = (ImDrawIdx)(vtx_index + 3);
04189                     vtx_write += 4;
04190                     vtx_index += 4;
04191                     idx_write += 6;
04192                 }
04193             }
04194         }
04195         x += char_width;
04196     }
04197 
04198     // Give back unused vertices (clipped ones, blanks) ~ this is essentially a PrimUnreserve() action.
04199     draw_list->VtxBuffer.Size = (int)(vtx_write - draw_list->VtxBuffer.Data); // Same as calling shrink()
04200     draw_list->IdxBuffer.Size = (int)(idx_write - draw_list->IdxBuffer.Data);
04201     draw_list->CmdBuffer[draw_list->CmdBuffer.Size - 1].ElemCount -= (idx_expected_size - draw_list->IdxBuffer.Size);
04202     draw_list->_VtxWritePtr = vtx_write;
04203     draw_list->_IdxWritePtr = idx_write;
04204     draw_list->_VtxCurrentIdx = vtx_index;
04205 }
