04223 // Render an arrow aimed to be aligned with text (p_min is a position in the same space text would be positioned). To e.g. denote expanded/collapsed state
04224 void ImGui::RenderArrow(ImDrawList* draw_list, ImVec2 pos, ImU32 col, ImGuiDir dir, float scale)
04225 {
04226     const float h = draw_list->_Data->FontSize * 1.00f;
04227     float r = h * 0.40f * scale;
04228     ImVec2 center = pos + ImVec2(h * 0.50f, h * 0.50f * scale);
04229 
04230     ImVec2 a, b, c;
04231     switch (dir)
04232     {
04233     case ImGuiDir_Up:
04234     case ImGuiDir_Down:
04235         if (dir == ImGuiDir_Up) r = -r;
04236         a = ImVec2(+0.000f, +0.750f) * r;
04237         b = ImVec2(-0.866f, -0.750f) * r;
04238         c = ImVec2(+0.866f, -0.750f) * r;
04239         break;
04240     case ImGuiDir_Left:
04241     case ImGuiDir_Right:
04242         if (dir == ImGuiDir_Left) r = -r;
04243         a = ImVec2(+0.750f, +0.000f) * r;
04244         b = ImVec2(-0.750f, +0.866f) * r;
04245         c = ImVec2(-0.750f, -0.866f) * r;
04246         break;
04247     case ImGuiDir_None:
04248     case ImGuiDir_COUNT:
04249         IM_ASSERT(0);
04250         break;
04251     }
04252     draw_list->AddTriangleFilled(center + a, center + b, center + c, col);
04253 }
