04261 void ImGui::RenderCheckMark(ImDrawList* draw_list, ImVec2 pos, ImU32 col, float sz)
04262 {
04263     float thickness = ImMax(sz / 5.0f, 1.0f);
04264     sz -= thickness * 0.5f;
04265     pos += ImVec2(thickness * 0.25f, thickness * 0.25f);
04266 
04267     float third = sz / 3.0f;
04268     float bx = pos.x + third;
04269     float by = pos.y + sz - third * 0.5f;
04270     draw_list->PathLineTo(ImVec2(bx - third, by - third));
04271     draw_list->PathLineTo(ImVec2(bx, by));
04272     draw_list->PathLineTo(ImVec2(bx + third * 2.0f, by - third * 2.0f));
04273     draw_list->PathStroke(col, 0, thickness);
04274 }
