04297 static inline float ImAcos01(float x)
04298 {
04299     if (x <= 0.0f) return IM_PI * 0.5f;
04300     if (x >= 1.0f) return 0.0f;
04301     return ImAcos(x);
04302     //return (-0.69813170079773212f * x * x - 0.87266462599716477f) * x + 1.5707963267948966f; // Cheap approximation, may be enough for what we do.
04303 }
04304 
04305 // FIXME: Cleanup and move code to ImDrawList.
04306 void ImGui::RenderRectFilledRangeH(ImDrawList* draw_list, const ImRect& rect, ImU32 col, float x_start_norm, float x_end_norm, float rounding)
04307 {
04308     if (x_end_norm == x_start_norm)
04309         return;
04310     if (x_start_norm > x_end_norm)
04311         ImSwap(x_start_norm, x_end_norm);
04312 
04313     ImVec2 p0 = ImVec2(ImLerp(rect.Min.x, rect.Max.x, x_start_norm), rect.Min.y);
04314     ImVec2 p1 = ImVec2(ImLerp(rect.Min.x, rect.Max.x, x_end_norm), rect.Max.y);
04315     if (rounding == 0.0f)
04316     {
04317         draw_list->AddRectFilled(p0, p1, col, 0.0f);
04318         return;
04319     }
04320 
04321     rounding = ImClamp(ImMin((rect.Max.x - rect.Min.x) * 0.5f, (rect.Max.y - rect.Min.y) * 0.5f) - 1.0f, 0.0f, rounding);
04322     const float inv_rounding = 1.0f / rounding;
04323     const float arc0_b = ImAcos01(1.0f - (p0.x - rect.Min.x) * inv_rounding);
04324     const float arc0_e = ImAcos01(1.0f - (p1.x - rect.Min.x) * inv_rounding);
04325     const float half_pi = IM_PI * 0.5f; // We will == compare to this because we know this is the exact value ImAcos01 can return.
04326     const float x0 = ImMax(p0.x, rect.Min.x + rounding);
04327     if (arc0_b == arc0_e)
04328     {
04329         draw_list->PathLineTo(ImVec2(x0, p1.y));
04330         draw_list->PathLineTo(ImVec2(x0, p0.y));
04331     }
04332     else if (arc0_b == 0.0f && arc0_e == half_pi)
04333     {
04334         draw_list->PathArcToFast(ImVec2(x0, p1.y - rounding), rounding, 3, 6); // BL
04335         draw_list->PathArcToFast(ImVec2(x0, p0.y + rounding), rounding, 6, 9); // TR
04336     }
04337     else
04338     {
04339         draw_list->PathArcTo(ImVec2(x0, p1.y - rounding), rounding, IM_PI - arc0_e, IM_PI - arc0_b); // BL
04340         draw_list->PathArcTo(ImVec2(x0, p0.y + rounding), rounding, IM_PI + arc0_b, IM_PI + arc0_e); // TR
04341     }
04342     if (p1.x > rect.Min.x + rounding)
04343     {
04344         const float arc1_b = ImAcos01(1.0f - (rect.Max.x - p1.x) * inv_rounding);
04345         const float arc1_e = ImAcos01(1.0f - (rect.Max.x - p0.x) * inv_rounding);
04346         const float x1 = ImMin(p1.x, rect.Max.x - rounding);
04347         if (arc1_b == arc1_e)
04348         {
04349             draw_list->PathLineTo(ImVec2(x1, p0.y));
04350             draw_list->PathLineTo(ImVec2(x1, p1.y));
04351         }
04352         else if (arc1_b == 0.0f && arc1_e == half_pi)
04353         {
04354             draw_list->PathArcToFast(ImVec2(x1, p0.y + rounding), rounding, 9, 12); // TR
04355             draw_list->PathArcToFast(ImVec2(x1, p1.y - rounding), rounding, 0, 3);  // BR
04356         }
04357         else
04358         {
04359             draw_list->PathArcTo(ImVec2(x1, p0.y + rounding), rounding, -arc1_e, -arc1_b); // TR
04360             draw_list->PathArcTo(ImVec2(x1, p1.y - rounding), rounding, +arc1_b, +arc1_e); // BR
04361         }
04362     }
04363     draw_list->PathFillConvex(col);
04364 }
04365 
04366 void ImGui::RenderRectFilledWithHole(ImDrawList* draw_list, const ImRect& outer, const ImRect& inner, ImU32 col, float rounding)
04367 {
04368     const bool fill_L = (inner.Min.x > outer.Min.x);
04369     const bool fill_R = (inner.Max.x < outer.Max.x);
04370     const bool fill_U = (inner.Min.y > outer.Min.y);
04371     const bool fill_D = (inner.Max.y < outer.Max.y);
04372     if (fill_L) draw_list->AddRectFilled(ImVec2(outer.Min.x, inner.Min.y), ImVec2(inner.Min.x, inner.Max.y), col, rounding, ImDrawFlags_RoundCornersNone | (fill_U ? 0 : ImDrawFlags_RoundCornersTopLeft)    | (fill_D ? 0 : ImDrawFlags_RoundCornersBottomLeft));
04373     if (fill_R) draw_list->AddRectFilled(ImVec2(inner.Max.x, inner.Min.y), ImVec2(outer.Max.x, inner.Max.y), col, rounding, ImDrawFlags_RoundCornersNone | (fill_U ? 0 : ImDrawFlags_RoundCornersTopRight)   | (fill_D ? 0 : ImDrawFlags_RoundCornersBottomRight));
04374     if (fill_U) draw_list->AddRectFilled(ImVec2(inner.Min.x, outer.Min.y), ImVec2(inner.Max.x, inner.Min.y), col, rounding, ImDrawFlags_RoundCornersNone | (fill_L ? 0 : ImDrawFlags_RoundCornersTopLeft)    | (fill_R ? 0 : ImDrawFlags_RoundCornersTopRight));
04375     if (fill_D) draw_list->AddRectFilled(ImVec2(inner.Min.x, inner.Max.y), ImVec2(inner.Max.x, outer.Max.y), col, rounding, ImDrawFlags_RoundCornersNone | (fill_L ? 0 : ImDrawFlags_RoundCornersBottomLeft) | (fill_R ? 0 : ImDrawFlags_RoundCornersBottomRight));
04376     if (fill_L && fill_U) draw_list->AddRectFilled(ImVec2(outer.Min.x, outer.Min.y), ImVec2(inner.Min.x, inner.Min.y), col, rounding, ImDrawFlags_RoundCornersTopLeft);
04377     if (fill_R && fill_U) draw_list->AddRectFilled(ImVec2(inner.Max.x, outer.Min.y), ImVec2(outer.Max.x, inner.Min.y), col, rounding, ImDrawFlags_RoundCornersTopRight);
04378     if (fill_L && fill_D) draw_list->AddRectFilled(ImVec2(outer.Min.x, inner.Max.y), ImVec2(inner.Min.x, outer.Max.y), col, rounding, ImDrawFlags_RoundCornersBottomLeft);
04379     if (fill_R && fill_D) draw_list->AddRectFilled(ImVec2(inner.Max.x, inner.Max.y), ImVec2(outer.Max.x, outer.Max.y), col, rounding, ImDrawFlags_RoundCornersBottomRight);
04380 }
04381 
04382 ImDrawFlags ImGui::CalcRoundingFlagsForRectInRect(const ImRect& r_in, const ImRect& r_outer, float threshold)
04383 {
04384     bool round_l = r_in.Min.x <= r_outer.Min.x + threshold;
04385     bool round_r = r_in.Max.x >= r_outer.Max.x - threshold;
04386     bool round_t = r_in.Min.y <= r_outer.Min.y + threshold;
04387     bool round_b = r_in.Max.y >= r_outer.Max.y - threshold;
04388     return ImDrawFlags_RoundCornersNone
04389         | ((round_t && round_l) ? ImDrawFlags_RoundCornersTopLeft : 0) | ((round_t && round_r) ? ImDrawFlags_RoundCornersTopRight : 0)
04390         | ((round_b && round_l) ? ImDrawFlags_RoundCornersBottomLeft : 0) | ((round_b && round_r) ? ImDrawFlags_RoundCornersBottomRight : 0);
04391 }
