04393 // Helper for ColorPicker4()
04394 // NB: This is rather brittle and will show artifact when rounding this enabled if rounded corners overlap multiple cells. Caller currently responsible for avoiding that.
04395 // Spent a non reasonable amount of time trying to getting this right for ColorButton with rounding+anti-aliasing+ImGuiColorEditFlags_HalfAlphaPreview flag + various grid sizes and offsets, and eventually gave up... probably more reasonable to disable rounding altogether.
04396 // FIXME: uses ImGui::GetColorU32
04397 void ImGui::RenderColorRectWithAlphaCheckerboard(ImDrawList* draw_list, ImVec2 p_min, ImVec2 p_max, ImU32 col, float grid_step, ImVec2 grid_off, float rounding, ImDrawFlags flags)
04398 {
04399     if ((flags & ImDrawFlags_RoundCornersMask_) == 0)
04400         flags = ImDrawFlags_RoundCornersDefault_;
04401     if (((col & IM_COL32_A_MASK) >> IM_COL32_A_SHIFT) < 0xFF)
04402     {
04403         ImU32 col_bg1 = GetColorU32(ImAlphaBlendColors(IM_COL32(204, 204, 204, 255), col));
04404         ImU32 col_bg2 = GetColorU32(ImAlphaBlendColors(IM_COL32(128, 128, 128, 255), col));
04405         draw_list->AddRectFilled(p_min, p_max, col_bg1, rounding, flags);
04406 
04407         int yi = 0;
04408         for (float y = p_min.y + grid_off.y; y < p_max.y; y += grid_step, yi++)
04409         {
04410             float y1 = ImClamp(y, p_min.y, p_max.y), y2 = ImMin(y + grid_step, p_max.y);
04411             if (y2 <= y1)
04412                 continue;
04413             for (float x = p_min.x + grid_off.x + (yi & 1) * grid_step; x < p_max.x; x += grid_step * 2.0f)
04414             {
04415                 float x1 = ImClamp(x, p_min.x, p_max.x), x2 = ImMin(x + grid_step, p_max.x);
04416                 if (x2 <= x1)
04417                     continue;
04418                 ImDrawFlags cell_flags = ImDrawFlags_RoundCornersNone;
04419                 if (y1 <= p_min.y) { if (x1 <= p_min.x) cell_flags |= ImDrawFlags_RoundCornersTopLeft; if (x2 >= p_max.x) cell_flags |= ImDrawFlags_RoundCornersTopRight; }
04420                 if (y2 >= p_max.y) { if (x1 <= p_min.x) cell_flags |= ImDrawFlags_RoundCornersBottomLeft; if (x2 >= p_max.x) cell_flags |= ImDrawFlags_RoundCornersBottomRight; }
04421 
04422                 // Combine flags
04423                 cell_flags = (flags == ImDrawFlags_RoundCornersNone || cell_flags == ImDrawFlags_RoundCornersNone) ? ImDrawFlags_RoundCornersNone : (cell_flags & flags);
04424                 draw_list->AddRectFilled(ImVec2(x1, y1), ImVec2(x2, y2), col_bg2, rounding, cell_flags);
04425             }
04426         }
04427     }
04428     else
04429     {
04430         draw_list->AddRectFilled(p_min, p_max, col, rounding, flags);
04431     }
04432 }
04433 
04434 //-----------------------------------------------------------------------------
04435 // [SECTION] Decompression code
04436 //-----------------------------------------------------------------------------
04437 // Compressed with stb_compress() then converted to a C array and encoded as base85.
04438 // Use the program in misc/fonts/binary_to_compressed_c.cpp to create the array from a TTF file.
04439 // The purpose of encoding as base85 instead of "0x00,0x01,..." style is only save on _source code_ size.
04440 // Decompression from stb.h (public domain) by Sean Barrett https://github.com/nothings/stb/blob/master/stb.h
04441 //-----------------------------------------------------------------------------
04442 
04443 static unsigned int stb_decompress_length(const unsigned char *input)
04444 {
04445     return (input[8] << 24) + (input[9] << 16) + (input[10] << 8) + input[11];
04446 }
04447 
04448 static unsigned char *stb__barrier_out_e, *stb__barrier_out_b;
04449 static const unsigned char *stb__barrier_in_b;
04450 static unsigned char *stb__dout;
04451 static void stb__match(const unsigned char *data, unsigned int length)
04452 {
04453     // INVERSE of memmove... write each byte before copying the next...
04454     IM_ASSERT(stb__dout + length <= stb__barrier_out_e);
04455     if (stb__dout + length > stb__barrier_out_e) { stb__dout += length; return; }
04456     if (data < stb__barrier_out_b) { stb__dout = stb__barrier_out_e+1; return; }
04457     while (length--) *stb__dout++ = *data++;
04458 }
04459 
04460 static void stb__lit(const unsigned char *data, unsigned int length)
04461 {
04462     IM_ASSERT(stb__dout + length <= stb__barrier_out_e);
04463     if (stb__dout + length > stb__barrier_out_e) { stb__dout += length; return; }
04464     if (data < stb__barrier_in_b) { stb__dout = stb__barrier_out_e+1; return; }
04465     memcpy(stb__dout, data, length);
04466     stb__dout += length;
04467 }
04468 
04469 #define stb__in2(x)   ((i[x] << 8) + i[(x)+1])
04470 #define stb__in3(x)   ((i[x] << 16) + stb__in2((x)+1))
04471 #define stb__in4(x)   ((i[x] << 24) + stb__in3((x)+1))
04472 
04473 static const unsigned char *stb_decompress_token(const unsigned char *i)
04474 {
04475     if (*i >= 0x20) { // use fewer if's for cases that expand small
04476         if (*i >= 0x80)       stb__match(stb__dout-i[1]-1, i[0] - 0x80 + 1), i += 2;
04477         else if (*i >= 0x40)  stb__match(stb__dout-(stb__in2(0) - 0x4000 + 1), i[2]+1), i += 3;
04478         else /* *i >= 0x20 */ stb__lit(i+1, i[0] - 0x20 + 1), i += 1 + (i[0] - 0x20 + 1);
04479     } else { // more ifs for cases that expand large, since overhead is amortized
04480         if (*i >= 0x18)       stb__match(stb__dout-(stb__in3(0) - 0x180000 + 1), i[3]+1), i += 4;
04481         else if (*i >= 0x10)  stb__match(stb__dout-(stb__in3(0) - 0x100000 + 1), stb__in2(3)+1), i += 5;
04482         else if (*i >= 0x08)  stb__lit(i+2, stb__in2(0) - 0x0800 + 1), i += 2 + (stb__in2(0) - 0x0800 + 1);
04483         else if (*i == 0x07)  stb__lit(i+3, stb__in2(1) + 1), i += 3 + (stb__in2(1) + 1);
04484         else if (*i == 0x06)  stb__match(stb__dout-(stb__in3(1)+1), i[4]+1), i += 5;
04485         else if (*i == 0x04)  stb__match(stb__dout-(stb__in3(1)+1), stb__in2(4)+1), i += 6;
04486     }
04487     return i;
04488 }
04489 
04490 static unsigned int stb_adler32(unsigned int adler32, unsigned char *buffer, unsigned int buflen)
04491 {
04492     const unsigned long ADLER_MOD = 65521;
04493     unsigned long s1 = adler32 & 0xffff, s2 = adler32 >> 16;
04494     unsigned long blocklen = buflen % 5552;
04495 
04496     unsigned long i;
04497     while (buflen) {
04498         for (i=0; i + 7 < blocklen; i += 8) {
04499             s1 += buffer[0], s2 += s1;
04500             s1 += buffer[1], s2 += s1;
04501             s1 += buffer[2], s2 += s1;
04502             s1 += buffer[3], s2 += s1;
04503             s1 += buffer[4], s2 += s1;
04504             s1 += buffer[5], s2 += s1;
04505             s1 += buffer[6], s2 += s1;
04506             s1 += buffer[7], s2 += s1;
04507 
04508             buffer += 8;
04509         }
04510 
04511         for (; i < blocklen; ++i)
04512             s1 += *buffer++, s2 += s1;
04513 
04514         s1 %= ADLER_MOD, s2 %= ADLER_MOD;
04515         buflen -= blocklen;
04516         blocklen = 5552;
04517     }
04518     return (unsigned int)(s2 << 16) + (unsigned int)s1;
04519 }
04520 
04521 static unsigned int stb_decompress(unsigned char *output, const unsigned char *i, unsigned int /*length*/)
04522 {
04523     if (stb__in4(0) != 0x57bC0000) return 0;
04524     if (stb__in4(4) != 0)          return 0; // error! stream is > 4GB
04525     const unsigned int olen = stb_decompress_length(i);
04526     stb__barrier_in_b = i;
04527     stb__barrier_out_e = output + olen;
04528     stb__barrier_out_b = output;
04529     i += 16;
04530 
04531     stb__dout = output;
04532     for (;;) {
04533         const unsigned char *old_i = i;
04534         i = stb_decompress_token(i);
04535         if (i == old_i) {
04536             if (*i == 0x05 && i[1] == 0xfa) {
04537                 IM_ASSERT(stb__dout == output + olen);
04538                 if (stb__dout != output + olen) return 0;
04539                 if (stb_adler32(1, output, olen) != (unsigned int) stb__in4(2))
04540                     return 0;
04541                 return olen;
04542             } else {
04543                 IM_ASSERT(0); /* NOTREACHED */
04544                 return 0;
04545             }
04546         }
04547         IM_ASSERT(stb__dout <= output + olen);
04548         if (stb__dout > output + olen)
04549             return 0;
04550     }
04551 }
